-- Baseline schema draft generated by scripts/dump_baseline_schema.py.
-- Source schema version: 105
-- Replace the migration chain only after the validation steps in
-- docs/migration-squash-plan.md pass.

CREATE TABLE source (
            id TEXT PRIMARY KEY,
            title TEXT NOT NULL,
            source_uri TEXT,
            space TEXT NOT NULL CHECK (length(trim(space)) > 0),
            work_id TEXT,
            created_at TEXT NOT NULL
        , identity_key TEXT, deleted_at TEXT, folder_id TEXT
            REFERENCES knowledge_folder(id) ON DELETE RESTRICT, document_metadata_json TEXT NOT NULL DEFAULT '{}', edit_revision INTEGER NOT NULL DEFAULT 1
            CHECK (edit_revision > 0));
CREATE TABLE source_snapshot (
            id TEXT PRIMARY KEY,
            source_id TEXT NOT NULL REFERENCES source(id) ON DELETE RESTRICT,
            content TEXT NOT NULL,
            content_hash TEXT NOT NULL,
            import_metadata_json TEXT NOT NULL DEFAULT '{}',
            created_at TEXT NOT NULL,
            UNIQUE(source_id, content_hash)
        );
CREATE TABLE chunk (
            id TEXT PRIMARY KEY,
            snapshot_id TEXT NOT NULL REFERENCES source_snapshot(id) ON DELETE RESTRICT,
            sequence INTEGER NOT NULL CHECK (sequence >= 0),
            start_offset INTEGER NOT NULL CHECK (start_offset >= 0),
            end_offset INTEGER NOT NULL CHECK (end_offset > start_offset),
            offset_unit TEXT NOT NULL DEFAULT 'unicode_codepoint',
            text TEXT NOT NULL,
            content_hash TEXT NOT NULL,
            chunker_version TEXT NOT NULL,
            created_at TEXT NOT NULL,
            UNIQUE(snapshot_id, chunker_version, sequence)
        );
CREATE TABLE evidence_span (
            id TEXT PRIMARY KEY,
            snapshot_id TEXT NOT NULL REFERENCES source_snapshot(id) ON DELETE RESTRICT,
            chunk_id TEXT REFERENCES chunk(id) ON DELETE RESTRICT,
            start_offset INTEGER NOT NULL CHECK (start_offset >= 0),
            end_offset INTEGER NOT NULL CHECK (end_offset > start_offset),
            quote_hash TEXT NOT NULL,
            created_at TEXT NOT NULL,
            CHECK (chunk_id IS NOT NULL OR snapshot_id IS NOT NULL)
        );
CREATE TABLE knowledge_item (
            id TEXT PRIMARY KEY,
            space TEXT NOT NULL CHECK (length(trim(space)) > 0),
            work_id TEXT,
            kind TEXT NOT NULL CHECK (length(trim(kind)) > 0),
            status TEXT NOT NULL CHECK (length(trim(status)) > 0),
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        , origin_parse_receipt_id TEXT
            REFERENCES knowledge_parse_receipt(id) ON DELETE RESTRICT, idempotency_key TEXT, published_graph_version_id TEXT);
CREATE TABLE knowledge_version (
            id TEXT PRIMARY KEY,
            item_id TEXT NOT NULL REFERENCES knowledge_item(id) ON DELETE RESTRICT,
            version INTEGER NOT NULL CHECK (version > 0),
            content_json TEXT NOT NULL,
            status TEXT NOT NULL CHECK (length(trim(status)) > 0),
            created_at TEXT NOT NULL,
            UNIQUE(item_id, version)
        );
CREATE TABLE knowledge_version_evidence (
            knowledge_version_id TEXT NOT NULL
                REFERENCES knowledge_version(id) ON DELETE RESTRICT,
            evidence_span_id TEXT NOT NULL
                REFERENCES evidence_span(id) ON DELETE RESTRICT,
            PRIMARY KEY(knowledge_version_id, evidence_span_id)
        );
CREATE TABLE knowledge_relation (
            id TEXT PRIMARY KEY,
            source_item_id TEXT NOT NULL REFERENCES knowledge_item(id) ON DELETE RESTRICT,
            target_item_id TEXT NOT NULL REFERENCES knowledge_item(id) ON DELETE RESTRICT,
            relation_type TEXT NOT NULL CHECK (length(trim(relation_type)) > 0),
            evidence_span_id TEXT NOT NULL REFERENCES evidence_span(id) ON DELETE RESTRICT,
            created_at TEXT NOT NULL,
            CHECK (source_item_id != target_item_id)
        );
CREATE TABLE embedding_projection (
            id TEXT PRIMARY KEY,
            target_type TEXT NOT NULL CHECK (length(trim(target_type)) > 0),
            target_id TEXT NOT NULL,
            provider TEXT NOT NULL CHECK (length(trim(provider)) > 0),
            model_id TEXT NOT NULL CHECK (length(trim(model_id)) > 0),
            model_version TEXT,
            dimensions INTEGER NOT NULL CHECK (dimensions > 0),
            content_hash TEXT NOT NULL,
            vector_blob BLOB,
            status TEXT NOT NULL CHECK (
                status IN ('pending', 'running', 'complete', 'failed')
            ),
            error_text TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL, vector_format TEXT NOT NULL DEFAULT 'f32le-v1',
            UNIQUE(target_type, target_id, provider, model_id, model_version, content_hash)
        );
CREATE TABLE workflow_run (
            run_id TEXT PRIMARY KEY,
            flow_id TEXT NOT NULL,
            version INTEGER NOT NULL CHECK (version > 0),
            flow_hash TEXT NOT NULL,
            spec_json TEXT NOT NULL,
            inputs_json TEXT NOT NULL,
            status TEXT NOT NULL CHECK (
                status IN ('queued', 'running', 'completed', 'failed')
            ),
            outputs_json TEXT,
            error TEXT,
            created_at TEXT NOT NULL,
            started_at TEXT,
            finished_at TEXT
        );
CREATE TABLE workflow_node_event (
            event_id INTEGER PRIMARY KEY AUTOINCREMENT,
            run_id TEXT NOT NULL REFERENCES workflow_run(run_id) ON DELETE RESTRICT,
            node_id TEXT NOT NULL,
            status TEXT NOT NULL,
            input_data_json TEXT,
            output_data_json TEXT,
            error TEXT,
            created_at TEXT NOT NULL
        );
CREATE VIRTUAL TABLE chunk_fts USING fts5(
            chunk_id UNINDEXED,
            tokenized_text,
            tokenize = 'unicode61'
        );
CREATE TABLE knowledge_project (
            id TEXT NOT NULL,
            space TEXT NOT NULL CHECK (space IN ('learning', 'writing')),
            title TEXT NOT NULL CHECK (length(trim(title)) > 0),
            description TEXT NOT NULL DEFAULT '',
            status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'deleted')),
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            deleted_at TEXT,
            PRIMARY KEY (space, id)
        );
CREATE VIRTUAL TABLE knowledge_item_fts USING fts5(
            item_id UNINDEXED,
            version_id UNINDEXED,
            title_tokens,
            body_tokens,
            tokenize = 'unicode61'
        );
CREATE TABLE knowledge_folder (
            id TEXT PRIMARY KEY,
            space TEXT NOT NULL CHECK (space IN ('learning', 'writing')),
            work_id TEXT,
            path TEXT NOT NULL CHECK (length(trim(path)) > 0),
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
CREATE TABLE writing_learning_source_reference (
            work_id TEXT NOT NULL,
            source_id TEXT NOT NULL REFERENCES source(id) ON DELETE RESTRICT,
            created_at TEXT NOT NULL,
            PRIMARY KEY (work_id, source_id)
        );
CREATE TABLE source_current_snapshot (
            source_id TEXT PRIMARY KEY REFERENCES source(id) ON DELETE RESTRICT,
            snapshot_id TEXT NOT NULL UNIQUE
                REFERENCES source_snapshot(id) ON DELETE RESTRICT
        );
CREATE TABLE assistant_conversation (
            id TEXT PRIMARY KEY,
            space TEXT NOT NULL CHECK (space IN ('learning', 'writing')),
            work_id TEXT,
            title TEXT NOT NULL CHECK (length(trim(title)) > 0),
            updated_at TEXT NOT NULL,
            messages_json TEXT NOT NULL
        , creative_state_json TEXT NOT NULL DEFAULT '{}', revision INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0));
CREATE TABLE writing_learning_scope_reference (
            work_space TEXT NOT NULL DEFAULT 'writing' CHECK (work_space = 'writing'),
            work_id TEXT NOT NULL,
            learning_work_id TEXT,
            folder_id TEXT REFERENCES knowledge_folder(id) ON DELETE CASCADE,
            created_at TEXT NOT NULL,
            FOREIGN KEY (work_space, work_id)
                REFERENCES knowledge_project(space, id) ON DELETE RESTRICT
        );
CREATE TABLE source_section (
            id TEXT PRIMARY KEY,
            snapshot_id TEXT NOT NULL REFERENCES source_snapshot(id) ON DELETE RESTRICT,
            sequence INTEGER NOT NULL CHECK (sequence >= 0),
            kind TEXT NOT NULL CHECK (
                kind IN ('chapter', 'front_matter', 'text_block')
            ),
            title TEXT NOT NULL CHECK (length(trim(title)) > 0),
            chapter_label TEXT,
            start_offset INTEGER NOT NULL CHECK (start_offset >= 0),
            end_offset INTEGER NOT NULL CHECK (end_offset > start_offset),
            offset_unit TEXT NOT NULL DEFAULT 'unicode_codepoint',
            content_hash TEXT NOT NULL,
            sectioning_version TEXT NOT NULL,
            created_at TEXT NOT NULL,
            UNIQUE(snapshot_id, sectioning_version, sequence),
            UNIQUE(snapshot_id, sectioning_version, start_offset)
        );
CREATE TABLE "knowledge_parse_receipt" (
            id TEXT PRIMARY KEY,
            space TEXT NOT NULL CHECK (space IN ('learning', 'writing')),
            work_id TEXT,
            source_id TEXT NOT NULL REFERENCES source(id) ON DELETE RESTRICT,
            snapshot_id TEXT NOT NULL REFERENCES source_snapshot(id) ON DELETE RESTRICT,
            branch_id TEXT,
            prompt_hash TEXT NOT NULL,
            route_fingerprint TEXT NOT NULL,
            status TEXT NOT NULL CHECK (status IN ('running', 'completed', 'failed')),
            candidate_count INTEGER NOT NULL DEFAULT 0 CHECK (candidate_count >= 0),
            coverage_total INTEGER NOT NULL DEFAULT 0 CHECK (coverage_total >= 0),
            coverage_completed INTEGER NOT NULL DEFAULT 0 CHECK (
                coverage_completed >= 0 AND coverage_completed <= coverage_total
            ),
            attempt_count INTEGER NOT NULL DEFAULT 1 CHECK (attempt_count > 0),
            provider_model TEXT,
            error_code TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL, parser_version TEXT NOT NULL DEFAULT 'legacy-v1', input_hash TEXT NOT NULL DEFAULT '', generation INTEGER NOT NULL DEFAULT 1 CHECK (generation > 0), diagnostic TEXT, parse_batch_id TEXT REFERENCES knowledge_parse_batch(id) ON DELETE SET NULL, review_status TEXT NOT NULL DEFAULT 'pending'
            CHECK (review_status IN ('pending', 'passed', 'incomplete')), review_diagnostic_json TEXT NOT NULL DEFAULT '{}',
            CHECK (
                (space = 'learning' AND branch_id IS NULL)
                OR (space = 'writing' AND work_id IS NOT NULL AND branch_id IS NOT NULL)
            ),
            FOREIGN KEY (space, work_id)
                REFERENCES knowledge_project(space, id) ON DELETE RESTRICT
        );
CREATE TABLE assistant_run (
            id TEXT PRIMARY KEY,
            turn_id TEXT NOT NULL UNIQUE,
            request_id TEXT NOT NULL UNIQUE,
            request_hash TEXT NOT NULL,
            conversation_id TEXT NOT NULL
                REFERENCES assistant_conversation(id) ON DELETE CASCADE,
            mode TEXT NOT NULL CHECK (mode IN ('workflow', 'deep_thinking')),
            status TEXT NOT NULL CHECK (status IN (
                'accepted', 'running', 'completed', 'failed', 'incomplete',
                'cancelled', 'interrupted'
            )),
            revision INTEGER NOT NULL CHECK (revision > 0),
            user_message_id TEXT NOT NULL,
            assistant_message_id TEXT NOT NULL,
            parent_run_id TEXT REFERENCES assistant_run(id) ON DELETE SET NULL,
            model TEXT,
            budget_profile TEXT NOT NULL CHECK (length(trim(budget_profile)) > 0),
            scope_json TEXT NOT NULL,
            scope_hash TEXT NOT NULL,
            protocol_messages_json TEXT NOT NULL DEFAULT '[]',
            protocol_revision INTEGER NOT NULL DEFAULT 0 CHECK (protocol_revision >= 0),
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            started_at TEXT,
            completed_at TEXT,
            last_seq INTEGER NOT NULL DEFAULT 0 CHECK (last_seq >= 0),
            error_code TEXT,
            error_stage TEXT,
            error_message TEXT
        , dispatch_policy TEXT NOT NULL DEFAULT 'legacy'
            CHECK (dispatch_policy IN ('legacy', 'auto')), dispatch_selected INTEGER NOT NULL DEFAULT 1
            CHECK (dispatch_selected IN (0, 1)), superseded_message_refs_json TEXT NOT NULL DEFAULT '[]'
            CHECK (json_valid(superseded_message_refs_json)), branch_retraction_status TEXT NOT NULL DEFAULT 'not_required'
            CHECK (branch_retraction_status IN ('not_required', 'pending', 'failed', 'completed')));
CREATE TABLE assistant_run_protocol_receipt (
            run_id TEXT NOT NULL REFERENCES assistant_run(id) ON DELETE CASCADE,
            action_id TEXT NOT NULL CHECK (length(trim(action_id)) > 0),
            action_hash TEXT NOT NULL,
            protocol_revision INTEGER NOT NULL CHECK (protocol_revision > 0),
            created_at TEXT NOT NULL,
            PRIMARY KEY (run_id, action_id)
        );
CREATE TABLE knowledge_parse_batch_item (
            batch_id TEXT NOT NULL
                REFERENCES knowledge_parse_batch(id) ON DELETE CASCADE,
            ordinal INTEGER NOT NULL CHECK (ordinal >= 0),
            source_id TEXT NOT NULL,
            source_title TEXT NOT NULL,
            folder_id TEXT,
            snapshot_id TEXT NOT NULL,
            status TEXT NOT NULL CHECK (status IN (
                'queued', 'running', 'completed', 'reused', 'failed'
            )),
            result_json TEXT,
            diagnostic TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL, section_ids_json TEXT NOT NULL DEFAULT '[]', stages_json TEXT NOT NULL DEFAULT '{}', stage_revision INTEGER NOT NULL DEFAULT 0 CHECK (stage_revision >= 0), execution_goal TEXT NOT NULL
            DEFAULT 'full_graph' CHECK (execution_goal IN ('reviewed_claims', 'full_graph')), base_publication_json TEXT NOT NULL
            DEFAULT '{}' CHECK (json_valid(base_publication_json)),
            PRIMARY KEY (batch_id, ordinal),
            UNIQUE (batch_id, source_id)
        );
CREATE TABLE source_import_batch (
            id TEXT PRIMARY KEY,
            space TEXT NOT NULL CHECK (space IN ('learning', 'writing')),
            work_id TEXT,
            folder_id TEXT,
            status TEXT NOT NULL CHECK (status IN (
                'queued', 'running', 'completed', 'completed_with_errors', 'interrupted'
            )),
            total INTEGER NOT NULL CHECK (total > 0),
            completed INTEGER NOT NULL DEFAULT 0 CHECK (completed >= 0),
            succeeded INTEGER NOT NULL DEFAULT 0 CHECK (succeeded >= 0),
            failed INTEGER NOT NULL DEFAULT 0 CHECK (failed >= 0),
            section_count INTEGER NOT NULL DEFAULT 0 CHECK (section_count >= 0),
            chapter_count INTEGER NOT NULL DEFAULT 0 CHECK (chapter_count >= 0),
            current_title TEXT,
            errors_json TEXT NOT NULL DEFAULT '[]',
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            finished_at TEXT
        );
CREATE TABLE source_import_batch_item (
            batch_id TEXT NOT NULL
                REFERENCES source_import_batch(id) ON DELETE CASCADE,
            ordinal INTEGER NOT NULL CHECK (ordinal >= 0),
            title TEXT NOT NULL,
            content TEXT,
            source_uri TEXT,
            folder_path TEXT,
            source_encoding TEXT NOT NULL CHECK (source_encoding IN ('utf-8', 'gb18030')),
            document_metadata_json TEXT NOT NULL DEFAULT '{}',
            status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
            error_text TEXT,
            updated_at TEXT NOT NULL, source_id TEXT REFERENCES source(id) ON DELETE SET NULL, section_count INTEGER NOT NULL DEFAULT 0 CHECK (section_count >= 0), chapter_count INTEGER NOT NULL DEFAULT 0 CHECK (chapter_count >= 0),
            PRIMARY KEY (batch_id, ordinal),
            CHECK ((status IN ('queued', 'running')) = (content IS NOT NULL))
        );
CREATE VIRTUAL TABLE knowledge_graph_fts USING fts5(
            item_id UNINDEXED,
            version_id UNINDEXED,
            card_key UNINDEXED,
            title_tokens,
            body_tokens,
            tokenize = 'unicode61'
        );
CREATE TABLE knowledge_graph_fts_state (
            id INTEGER PRIMARY KEY CHECK (id = 1),
            index_version INTEGER NOT NULL
        );
CREATE TABLE prose_artifact_state (
            artifact_id TEXT PRIMARY KEY CHECK (length(trim(artifact_id)) BETWEEN 1 AND 200),
            work_id TEXT NOT NULL CHECK (length(trim(work_id)) BETWEEN 1 AND 200),
            conversation_id TEXT NOT NULL CHECK (length(trim(conversation_id)) BETWEEN 1 AND 200),
            source_message_id TEXT NOT NULL CHECK (length(trim(source_message_id)) BETWEEN 1 AND 200),
            current_revision INTEGER NOT NULL CHECK (current_revision > 0),
            accepted_revision INTEGER NOT NULL DEFAULT 0 CHECK (
                accepted_revision >= 0 AND accepted_revision <= current_revision
            ),
            updated_at TEXT NOT NULL
        , chapter_id TEXT, folder_id TEXT REFERENCES knowledge_folder(id) ON DELETE SET NULL);
CREATE TABLE prose_artifact_revision (
            artifact_id TEXT NOT NULL
                REFERENCES prose_artifact_state(artifact_id) ON DELETE CASCADE,
            revision INTEGER NOT NULL CHECK (revision > 0),
            content_hash TEXT NOT NULL CHECK (length(content_hash) = 64),
            parent_revision INTEGER,
            status TEXT NOT NULL CHECK (status IN ('candidate', 'adopted', 'rejected', 'superseded')),
            provenance_json TEXT NOT NULL,
            created_at TEXT NOT NULL, review_status TEXT NOT NULL
            DEFAULT 'not_reviewed'
            CHECK(review_status IN ('not_reviewed', 'reviewed', 'needs_attention')),
            PRIMARY KEY (artifact_id, revision),
            CHECK (parent_revision IS NULL OR parent_revision < revision)
        );
CREATE TABLE creative_plan_state (
            work_id TEXT PRIMARY KEY CHECK (length(trim(work_id)) BETWEEN 1 AND 200),
            current_revision INTEGER NOT NULL DEFAULT 0 CHECK (current_revision >= 0),
            adopted_revision INTEGER NOT NULL DEFAULT 0 CHECK (
                adopted_revision >= 0 AND adopted_revision <= current_revision
            ),
            updated_at TEXT
        , folder_id TEXT REFERENCES knowledge_folder(id) ON DELETE SET NULL);
CREATE TABLE creative_plan_assessment (
            work_id TEXT NOT NULL
                REFERENCES creative_plan_state(work_id) ON DELETE CASCADE,
            revision INTEGER NOT NULL CHECK (revision > 0),
            content_hash TEXT NOT NULL,
            status TEXT NOT NULL CHECK (status IN ('ready', 'needs_work')),
            assessment_json TEXT NOT NULL,
            assessed_at TEXT NOT NULL,
            PRIMARY KEY (work_id, revision)
        );
CREATE TABLE prose_detector_comparison (
            comparison_id TEXT PRIMARY KEY CHECK (length(trim(comparison_id)) BETWEEN 1 AND 200),
            work_id TEXT NOT NULL CHECK (length(trim(work_id)) BETWEEN 1 AND 200),
            detector_name TEXT NOT NULL CHECK (length(trim(detector_name)) BETWEEN 1 AND 120),
            detector_version TEXT NOT NULL CHECK (length(trim(detector_version)) BETWEEN 1 AND 120),
            detector_settings TEXT NOT NULL DEFAULT '',
            source_artifact_id TEXT NOT NULL,
            source_revision INTEGER NOT NULL CHECK (source_revision > 0),
            source_content_hash TEXT NOT NULL CHECK (length(source_content_hash) = 64),
            source_score REAL NOT NULL CHECK (source_score >= 0 AND source_score <= 100),
            candidate_artifact_id TEXT NOT NULL,
            candidate_revision INTEGER NOT NULL CHECK (candidate_revision > 0),
            candidate_content_hash TEXT NOT NULL CHECK (length(candidate_content_hash) = 64),
            candidate_score REAL NOT NULL CHECK (candidate_score >= 0 AND candidate_score <= 100),
            measured_at TEXT NOT NULL,
            created_at TEXT NOT NULL,
            FOREIGN KEY (source_artifact_id, source_revision)
                REFERENCES prose_artifact_revision(artifact_id, revision) ON DELETE CASCADE,
            FOREIGN KEY (candidate_artifact_id, candidate_revision)
                REFERENCES prose_artifact_revision(artifact_id, revision) ON DELETE CASCADE
        );
CREATE TABLE prose_chapter_head (
            work_id TEXT NOT NULL,
            chapter_id TEXT NOT NULL CHECK(length(trim(chapter_id)) BETWEEN 1 AND 200),
            head_version INTEGER NOT NULL CHECK(head_version >= 0),
            adopted_artifact_id TEXT,
            adopted_revision INTEGER,
            adopted_hash TEXT CHECK(adopted_hash IS NULL OR length(adopted_hash) = 64),
            updated_at TEXT NOT NULL,
            PRIMARY KEY(work_id, chapter_id),
            CHECK((adopted_artifact_id IS NULL AND adopted_revision IS NULL AND adopted_hash IS NULL)
               OR (adopted_artifact_id IS NOT NULL AND adopted_revision IS NOT NULL AND adopted_hash IS NOT NULL)),
            FOREIGN KEY(adopted_artifact_id, adopted_revision)
                REFERENCES prose_artifact_revision(artifact_id, revision)
        );
CREATE TABLE prose_lifecycle_event (
            event_id INTEGER PRIMARY KEY AUTOINCREMENT,
            operation_id TEXT NOT NULL,
            work_id TEXT NOT NULL,
            chapter_id TEXT,
            head_version INTEGER,
            event_type TEXT NOT NULL CHECK(event_type IN ('draft_saved', 'adopted', 'revoked')),
            artifact_id TEXT,
            revision INTEGER,
            content_hash TEXT,
            event_json TEXT NOT NULL,
            delivery_status TEXT NOT NULL DEFAULT 'pending'
                CHECK(delivery_status IN ('pending', 'acknowledged')),
            delivery_consumer TEXT,
            delivery_receipt_json TEXT,
            created_at TEXT NOT NULL,
            acknowledged_at TEXT,
            UNIQUE(work_id, operation_id, event_type),
            CHECK((delivery_status = 'pending' AND delivery_consumer IS NULL
                   AND delivery_receipt_json IS NULL AND acknowledged_at IS NULL)
               OR (delivery_status = 'acknowledged' AND delivery_consumer IS NOT NULL
                   AND delivery_receipt_json IS NOT NULL AND acknowledged_at IS NOT NULL))
        );
CREATE TABLE knowledge_graph_projection (
            candidate_item_id TEXT PRIMARY KEY REFERENCES knowledge_item(id) ON DELETE CASCADE,
            candidate_version_id TEXT NOT NULL REFERENCES knowledge_version(id) ON DELETE RESTRICT,
            space TEXT NOT NULL CHECK (space IN ('learning','writing')),
            work_id TEXT,
            branch_id TEXT,
            candidate_role TEXT NOT NULL CHECK (candidate_role IN ('entity','fact')),
            identity_group_id TEXT,
            identity_display_name TEXT,
            proposition_id TEXT,
            target_identity_group_id TEXT,
            category TEXT NOT NULL,
            predicate TEXT NOT NULL,
            value_json TEXT,
            state_slot TEXT,
            state_value_status TEXT NOT NULL CHECK (state_value_status IN ('known_value','explicit_unknown')),
            story_time_expression TEXT,
            source_chapter_order INTEGER CHECK (source_chapter_order IS NULL OR source_chapter_order >= 0),
            narrative_order INTEGER CHECK (narrative_order IS NULL OR narrative_order >= 0),
            evidence_start_offset INTEGER CHECK (evidence_start_offset IS NULL OR evidence_start_offset >= 0),
            evidence_end_offset INTEGER CHECK (evidence_end_offset IS NULL OR evidence_end_offset >= 0),
            story_order INTEGER CHECK (story_order IS NULL OR story_order >= 0),
            valid_from_story_order INTEGER CHECK (valid_from_story_order IS NULL OR valid_from_story_order >= 0),
            valid_until_story_order INTEGER CHECK (valid_until_story_order IS NULL OR valid_until_story_order >= 0),
            claim_basis TEXT NOT NULL,
            asserted_by_identity_group_id TEXT,
            observed_by_identity_group_id TEXT,
            holder_identity_group_id TEXT,
            audience_identity_group_ids_json TEXT NOT NULL DEFAULT '[]',
            semantic_assessment TEXT NOT NULL DEFAULT 'unresolved'
                CHECK (semantic_assessment IN ('unresolved','supported','attributed','conflicted','uncertain','inferred','excluded')),
            updated_at TEXT NOT NULL,
            CHECK ((space='learning') OR (space='writing' AND work_id IS NOT NULL)),
            CHECK ((evidence_start_offset IS NULL AND evidence_end_offset IS NULL)
                OR (evidence_start_offset IS NOT NULL AND evidence_end_offset > evidence_start_offset)),
            CHECK (valid_from_story_order IS NULL OR valid_until_story_order IS NULL
                OR valid_from_story_order <= valid_until_story_order),
            CHECK (category='temporal_state' OR (state_slot IS NULL AND state_value_status='known_value')),
            FOREIGN KEY (space, work_id) REFERENCES knowledge_project(space,id) ON DELETE RESTRICT
        );
CREATE TABLE knowledge_projection_dependency (
            dependency_id TEXT PRIMARY KEY CHECK (length(trim(dependency_id)) BETWEEN 1 AND 200),
            space TEXT NOT NULL DEFAULT 'writing' CHECK (space='writing'),
            work_id TEXT NOT NULL,
            branch_id TEXT NOT NULL,
            consumer_kind TEXT NOT NULL CHECK (length(trim(consumer_kind)) BETWEEN 1 AND 80),
            consumer_id TEXT NOT NULL CHECK (length(trim(consumer_id)) BETWEEN 1 AND 200),
            consumer_revision TEXT NOT NULL CHECK (length(trim(consumer_revision)) BETWEEN 1 AND 200),
            upstream_kind TEXT NOT NULL CHECK (upstream_kind IN ('knowledge_version','prose_artifact')),
            knowledge_item_id TEXT REFERENCES knowledge_item(id) ON DELETE RESTRICT,
            knowledge_version_id TEXT REFERENCES knowledge_version(id) ON DELETE RESTRICT,
            artifact_id TEXT,
            artifact_revision INTEGER,
            artifact_hash TEXT,
            purpose TEXT NOT NULL CHECK (purpose IN ('work_fact','canon_fact','story_context','chapter_review','author_decision')),
            status TEXT NOT NULL DEFAULT 'current' CHECK (status IN ('current','invalidated')),
            invalidated_by_event_id INTEGER REFERENCES prose_lifecycle_event(event_id) ON DELETE RESTRICT,
            invalidation_reason TEXT,
            created_at TEXT NOT NULL,
            invalidated_at TEXT,
            CHECK ((upstream_kind='knowledge_version'
                AND knowledge_item_id IS NOT NULL AND knowledge_version_id IS NOT NULL
                AND artifact_id IS NULL AND artifact_revision IS NULL AND artifact_hash IS NULL)
              OR (upstream_kind='prose_artifact'
                AND knowledge_item_id IS NULL AND knowledge_version_id IS NULL
                AND artifact_id IS NOT NULL AND artifact_revision > 0 AND length(artifact_hash)=64)),
            FOREIGN KEY (space,work_id) REFERENCES knowledge_project(space,id) ON DELETE RESTRICT
        );
CREATE TABLE knowledge_prose_event_receipt (
            event_id INTEGER PRIMARY KEY REFERENCES prose_lifecycle_event(event_id) ON DELETE RESTRICT,
            space TEXT NOT NULL DEFAULT 'writing' CHECK (space='writing'),
            work_id TEXT NOT NULL,
            chapter_id TEXT,
            head_version INTEGER,
            event_type TEXT NOT NULL CHECK (event_type IN ('draft_saved','adopted','revoked')),
            artifact_id TEXT NOT NULL,
            revision INTEGER NOT NULL CHECK (revision > 0),
            content_hash TEXT NOT NULL CHECK (length(content_hash)=64),
            previous_head_json TEXT,
            payload_hash TEXT NOT NULL CHECK (length(payload_hash)=64),
            outcome TEXT NOT NULL CHECK (outcome IN ('ignored_draft_saved','adoption_invalidated','revocation_invalidated')),
            invalidated_dependency_count INTEGER NOT NULL DEFAULT 0 CHECK (invalidated_dependency_count >= 0),
            outcome_json TEXT NOT NULL DEFAULT '{}',
            pending_fact_refresh INTEGER NOT NULL DEFAULT 0 CHECK (pending_fact_refresh IN (0,1)),
            processed_at TEXT NOT NULL,
            FOREIGN KEY (space,work_id) REFERENCES knowledge_project(space,id) ON DELETE RESTRICT
        );
CREATE TABLE knowledge_prose_refresh (
            event_id INTEGER PRIMARY KEY
                REFERENCES knowledge_prose_event_receipt(event_id) ON DELETE RESTRICT,
            space TEXT NOT NULL DEFAULT 'writing' CHECK (space='writing'),
            work_id TEXT NOT NULL,
            chapter_id TEXT NOT NULL,
            head_version INTEGER NOT NULL CHECK (head_version > 0),
            event_type TEXT NOT NULL CHECK (event_type IN ('adopted','revoked')),
            artifact_id TEXT NOT NULL,
            revision INTEGER NOT NULL CHECK (revision > 0),
            content_hash TEXT NOT NULL CHECK (length(content_hash)=64),
            payload_hash TEXT NOT NULL CHECK (length(payload_hash)=64),
            source_id TEXT REFERENCES source(id) ON DELETE RESTRICT,
            snapshot_id TEXT REFERENCES source_snapshot(id) ON DELETE RESTRICT,
            source_content_hash TEXT CHECK (source_content_hash IS NULL OR length(source_content_hash)=64),
            branch_id TEXT,
            client_batch_id TEXT UNIQUE,
            parse_batch_id TEXT REFERENCES knowledge_parse_batch(id) ON DELETE RESTRICT,
            status TEXT NOT NULL CHECK (status IN (
                'blocked_missing_branch','queued','running','completed','failed','superseded','revoked'
            )),
            error_code TEXT,
            updated_at TEXT NOT NULL,
            FOREIGN KEY (space, work_id) REFERENCES knowledge_project(space,id) ON DELETE RESTRICT,
            CHECK ((snapshot_id IS NULL AND source_content_hash IS NULL)
                OR (snapshot_id IS NOT NULL AND source_id IS NOT NULL
                    AND source_content_hash IS NOT NULL))
        );
CREATE TABLE knowledge_source_ownership_transfer (
            operation_id TEXT PRIMARY KEY CHECK (length(trim(operation_id)) > 0),
            request_hash TEXT NOT NULL CHECK (length(request_hash) = 64),
            expected_fingerprint TEXT NOT NULL CHECK (length(expected_fingerprint) = 64),
            source_space TEXT NOT NULL CHECK (source_space IN ('learning', 'writing')),
            source_work_id TEXT,
            target_work_id TEXT NOT NULL,
            status TEXT NOT NULL CHECK (status IN ('applying', 'completed')),
            source_count INTEGER NOT NULL CHECK (source_count > 0),
            created_folder_count INTEGER NOT NULL DEFAULT -1 CHECK (created_folder_count >= -1),
            created_at TEXT NOT NULL,
            CHECK ((status = 'applying' AND created_folder_count = -1)
                OR (status = 'completed' AND created_folder_count >= 0))
        );
CREATE TABLE knowledge_source_ownership_transfer_item (
            operation_id TEXT NOT NULL
                REFERENCES knowledge_source_ownership_transfer(operation_id) ON DELETE CASCADE,
            source_id TEXT NOT NULL REFERENCES source(id) ON DELETE RESTRICT,
            source_space TEXT NOT NULL CHECK (source_space IN ('learning', 'writing')),
            source_work_id TEXT,
            target_work_id TEXT NOT NULL,
            target_folder_id TEXT,
            target_identity_key TEXT NOT NULL,
            PRIMARY KEY (operation_id, source_id)
        );
CREATE TABLE embedding_projection_backfill (
            route_fingerprint TEXT PRIMARY KEY,
            cursor_target_id TEXT NOT NULL DEFAULT '',
            complete INTEGER NOT NULL DEFAULT 0 CHECK (complete IN (0, 1)),
            updated_at TEXT NOT NULL
        , status TEXT NOT NULL DEFAULT 'pending'
            CHECK (status IN ('pending', 'completed', 'retired')), retired_at TEXT, retired_reason TEXT, superseded_scope_key TEXT);
CREATE TABLE knowledge_source_idempotency_receipt (
            idempotency_key TEXT PRIMARY KEY CHECK (length(idempotency_key) = 64),
            source_id TEXT NOT NULL REFERENCES source(id) ON DELETE RESTRICT,
            space TEXT NOT NULL CHECK (space IN ('learning', 'writing')),
            work_id TEXT,
            result_json TEXT NOT NULL,
            created_at TEXT NOT NULL
        );
CREATE TABLE chapter_outline_state (
            outline_id TEXT PRIMARY KEY CHECK (length(trim(outline_id)) BETWEEN 1 AND 200),
            work_id TEXT NOT NULL CHECK (length(trim(work_id)) BETWEEN 1 AND 200),
            chapter_id TEXT NOT NULL CHECK (length(trim(chapter_id)) BETWEEN 1 AND 200),
            folder_id TEXT REFERENCES knowledge_folder(id) ON DELETE SET NULL,
            current_revision INTEGER NOT NULL CHECK (current_revision > 0),
            updated_at TEXT NOT NULL, lifecycle_status TEXT NOT NULL DEFAULT 'active'
            CHECK (lifecycle_status IN ('active', 'branch_retracted')),
            UNIQUE(work_id, chapter_id)
        );
CREATE TABLE chapter_outline_revision (
            outline_id TEXT NOT NULL
                REFERENCES chapter_outline_state(outline_id) ON DELETE CASCADE,
            revision INTEGER NOT NULL CHECK (revision > 0),
            title TEXT NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 240),
            content_hash TEXT NOT NULL CHECK (length(content_hash) = 64),
            parent_revision INTEGER,
            provenance_json TEXT NOT NULL,
            created_at TEXT NOT NULL,
            PRIMARY KEY(outline_id, revision),
            CHECK (parent_revision IS NULL OR parent_revision < revision)
        );
CREATE TABLE knowledge_card_candidate (
            candidate_item_id TEXT PRIMARY KEY
                REFERENCES knowledge_item(id) ON DELETE CASCADE,
            candidate_version_id TEXT NOT NULL
                REFERENCES knowledge_version(id) ON DELETE CASCADE,
            scope_key TEXT NOT NULL,
            kind TEXT NOT NULL,
            card_key TEXT NOT NULL,
            card_category TEXT NOT NULL CHECK (card_category IN (
                'character','prop','ability','location','organization',
                'event','facts','timeline','claims','other'
            )),
            candidate_role TEXT,
            identity_is_canonical INTEGER NOT NULL DEFAULT 0
                CHECK (identity_is_canonical IN (0,1)),
            source_chapter_order INTEGER,
            updated_at TEXT NOT NULL
        , search_fields_json TEXT NOT NULL DEFAULT '[]');
CREATE TABLE knowledge_card_summary (
            scope_key TEXT NOT NULL,
            card_key TEXT NOT NULL,
            view_category TEXT NOT NULL,
            card_category TEXT NOT NULL CHECK (card_category IN (
                'character','prop','ability','location','organization',
                'event','facts','timeline','claims','other'
            )),
            representative_item_id TEXT NOT NULL
                REFERENCES knowledge_item(id) ON DELETE CASCADE,
            representative_version_id TEXT NOT NULL
                REFERENCES knowledge_version(id) ON DELETE CASCADE,
            candidate_count INTEGER NOT NULL CHECK (candidate_count > 0),
            updated_at TEXT NOT NULL,
            PRIMARY KEY (scope_key, card_key, view_category),
            CHECK (view_category = 'all' OR view_category = card_category)
        );
CREATE TABLE knowledge_card_index_state (
            id INTEGER PRIMARY KEY CHECK (id = 1),
            index_version INTEGER NOT NULL
        );
CREATE TABLE knowledge_card_search_bigram (
            candidate_item_id TEXT NOT NULL
                REFERENCES knowledge_card_candidate(candidate_item_id) ON DELETE CASCADE,
            scope_key TEXT NOT NULL,
            gram TEXT NOT NULL,
            PRIMARY KEY(candidate_item_id, gram)
        ) WITHOUT ROWID;
CREATE TABLE knowledge_source_title_search_gram (
            source_id TEXT NOT NULL REFERENCES source(id) ON DELETE CASCADE,
            scope_key TEXT NOT NULL,
            gram TEXT NOT NULL,
            PRIMARY KEY(source_id, gram)
        ) WITHOUT ROWID;
CREATE TABLE knowledge_source_title_search_state (
            id INTEGER PRIMARY KEY CHECK (id = 1),
            index_version INTEGER NOT NULL
        );
CREATE TABLE knowledge_card_candidate_evidence (
            candidate_item_id TEXT NOT NULL
                REFERENCES knowledge_card_candidate(candidate_item_id) ON DELETE CASCADE,
            candidate_version_id TEXT NOT NULL
                REFERENCES knowledge_version(id) ON DELETE CASCADE,
            evidence_span_id TEXT NOT NULL
                REFERENCES evidence_span(id) ON DELETE CASCADE,
            source_id TEXT NOT NULL REFERENCES source(id) ON DELETE CASCADE,
            PRIMARY KEY(candidate_version_id, evidence_span_id)
        ) WITHOUT ROWID;
CREATE TABLE knowledge_card_candidate_evidence_state (
            id INTEGER PRIMARY KEY CHECK (id = 1),
            index_version INTEGER NOT NULL
        );
CREATE TABLE knowledge_card_folder_summary (
            scope_key TEXT NOT NULL,
            folder_id TEXT NOT NULL REFERENCES knowledge_folder(id) ON DELETE CASCADE,
            card_key TEXT NOT NULL,
            view_category TEXT NOT NULL,
            card_category TEXT NOT NULL CHECK (card_category IN (
                'character','prop','ability','location','organization',
                'event','facts','timeline','claims','other'
            )),
            representative_item_id TEXT NOT NULL
                REFERENCES knowledge_item(id) ON DELETE CASCADE,
            representative_version_id TEXT NOT NULL
                REFERENCES knowledge_version(id) ON DELETE CASCADE,
            candidate_count INTEGER NOT NULL CHECK (candidate_count > 0),
            updated_at TEXT NOT NULL,
            PRIMARY KEY (scope_key, folder_id, card_key, view_category),
            CHECK (view_category = 'all' OR view_category = card_category)
        );
CREATE TABLE knowledge_card_folder_summary_state (
            id INTEGER PRIMARY KEY CHECK (id = 1),
            index_version INTEGER NOT NULL
        );
CREATE TABLE knowledge_card_folder_summary_dirty (
            scope_key TEXT NOT NULL,
            folder_id TEXT NOT NULL REFERENCES knowledge_folder(id) ON DELETE CASCADE,
            PRIMARY KEY(scope_key, folder_id)
        ) WITHOUT ROWID;
CREATE TABLE assistant_run_event (
            run_id TEXT NOT NULL REFERENCES assistant_run(id) ON DELETE CASCADE,
            seq INTEGER NOT NULL CHECK (seq > 0),
            event_key TEXT NOT NULL CHECK (length(trim(event_key)) > 0),
            event_hash TEXT NOT NULL,
            event_type TEXT NOT NULL CHECK (event_type IN (
                'accepted', 'activity.started', 'activity.completed',
                'context.compacted', 'answer.delta', 'answer.committed',
                'usage.updated', 'model.receipt', 'run.completed', 'run.failed',
                'run.incomplete', 'run.cancelled', 'run.interrupted',
                'prose.draft_saved'
            )),
            occurred_at TEXT NOT NULL,
            parent_run_id TEXT REFERENCES assistant_run(id) ON DELETE SET NULL,
            data_json TEXT NOT NULL,
            PRIMARY KEY (run_id, seq),
            UNIQUE (run_id, event_key)
        );
CREATE TABLE knowledge_graph_identity_review_index (
            candidate_item_id TEXT NOT NULL REFERENCES knowledge_item(id) ON DELETE CASCADE,
            candidate_version_id TEXT NOT NULL REFERENCES knowledge_version(id) ON DELETE CASCADE,
            space TEXT NOT NULL CHECK (space IN ('learning', 'writing')),
            work_id TEXT,
            source_id TEXT NOT NULL REFERENCES source(id) ON DELETE CASCADE,
            role TEXT NOT NULL CHECK (role IN (
                'subject', 'target', 'asserted_by', 'observed_by', 'holder', 'audience'
            )),
            audience_index INTEGER NOT NULL DEFAULT -1 CHECK (audience_index >= -1),
            source_chapter_order INTEGER NOT NULL DEFAULT 9223372036854775807,
            evidence_quote_start INTEGER NOT NULL DEFAULT 9223372036854775807,
            mention_name TEXT NOT NULL CHECK (length(trim(mention_name)) > 0),
            entity_ref TEXT,
            identity_group_id TEXT,
            decision_json TEXT,
            PRIMARY KEY (candidate_item_id, role, audience_index)
        );
CREATE TABLE knowledge_parse_unit_attempt (
            id TEXT PRIMARY KEY,
            receipt_id TEXT NOT NULL
                REFERENCES knowledge_parse_receipt(id) ON DELETE RESTRICT,
            generation INTEGER NOT NULL CHECK (generation > 0),
            group_ref TEXT NOT NULL CHECK (length(trim(group_ref)) > 0),
            attempt INTEGER NOT NULL CHECK (attempt > 0),
            input_hash TEXT NOT NULL CHECK (length(input_hash) = 64),
            prompt_hash TEXT NOT NULL CHECK (length(prompt_hash) = 64),
            provider_model TEXT NOT NULL CHECK (length(trim(provider_model)) > 0),
            status TEXT NOT NULL CHECK (
                status IN ('requested', 'received', 'validated', 'failed')
            ),
            request_json TEXT NOT NULL,
            response_text TEXT,
            validation_json TEXT NOT NULL DEFAULT '{}',
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            UNIQUE (receipt_id, generation, group_ref, attempt),
            CHECK (status != 'requested' OR response_text IS NULL)
        );
CREATE TABLE knowledge_learning_work_folder (
            space TEXT NOT NULL DEFAULT 'learning' CHECK (space = 'learning'),
            work_id TEXT NOT NULL,
            folder_id TEXT NOT NULL REFERENCES knowledge_folder(id) ON DELETE RESTRICT,
            created_at TEXT NOT NULL,
            PRIMARY KEY (work_id, folder_id),
            FOREIGN KEY (space, work_id)
                REFERENCES knowledge_project(space, id) ON DELETE RESTRICT
        );
CREATE TABLE knowledge_story_order_revision (
            space TEXT NOT NULL DEFAULT 'learning' CHECK (space = 'learning'),
            work_id TEXT NOT NULL,
            revision INTEGER NOT NULL CHECK (revision > 0),
            manifest_hash TEXT NOT NULL CHECK (length(manifest_hash) = 64),
            coverage_status TEXT NOT NULL CHECK (coverage_status IN ('complete', 'partial')),
            entry_count INTEGER NOT NULL CHECK (entry_count > 0),
            expected_source_count INTEGER NOT NULL CHECK (expected_source_count >= entry_count),
            created_at TEXT NOT NULL,
            PRIMARY KEY (work_id, revision),
            FOREIGN KEY (space, work_id)
                REFERENCES knowledge_project(space, id) ON DELETE RESTRICT,
            CHECK (
                (coverage_status = 'complete' AND entry_count = expected_source_count)
                OR coverage_status = 'partial'
            )
        );
CREATE TABLE knowledge_story_order_entry (
            work_id TEXT NOT NULL,
            revision INTEGER NOT NULL,
            narrative_ordinal INTEGER NOT NULL CHECK (narrative_ordinal >= 0),
            source_id TEXT NOT NULL REFERENCES source(id) ON DELETE RESTRICT,
            snapshot_id TEXT NOT NULL REFERENCES source_snapshot(id) ON DELETE RESTRICT,
            content_hash TEXT NOT NULL CHECK (length(content_hash) = 64),
            chapter_title TEXT NOT NULL CHECK (length(trim(chapter_title)) > 0),
            chapter_label TEXT,
            PRIMARY KEY (work_id, revision, narrative_ordinal),
            UNIQUE (work_id, revision, source_id),
            FOREIGN KEY (work_id, revision)
                REFERENCES knowledge_story_order_revision(work_id, revision) ON DELETE RESTRICT
        );
CREATE TABLE knowledge_story_order_current (
            work_id TEXT PRIMARY KEY,
            revision INTEGER NOT NULL,
            updated_at TEXT NOT NULL,
            FOREIGN KEY (work_id, revision)
                REFERENCES knowledge_story_order_revision(work_id, revision) ON DELETE RESTRICT
        );
CREATE TABLE writing_consistency_check_job (
            id TEXT PRIMARY KEY CHECK (length(trim(id)) BETWEEN 1 AND 200),
            space TEXT NOT NULL DEFAULT 'writing' CHECK (space = 'writing'),
            work_id TEXT NOT NULL,
            artifact_id TEXT NOT NULL CHECK (length(trim(artifact_id)) BETWEEN 1 AND 200),
            revision INTEGER NOT NULL CHECK (revision > 0),
            content_hash TEXT NOT NULL CHECK (
                length(content_hash) = 64 AND content_hash NOT GLOB '*[^0-9a-f]*'
            ),
            branch_id TEXT,
            instructions TEXT NOT NULL DEFAULT '',
            instructions_hash TEXT NOT NULL CHECK (
                length(instructions_hash) = 64 AND instructions_hash NOT GLOB '*[^0-9a-f]*'
            ),
            reference_source_ids_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(reference_source_ids_json)),
            request_hash TEXT NOT NULL UNIQUE CHECK (
                length(request_hash) = 64 AND request_hash NOT GLOB '*[^0-9a-f]*'
            ),
            status TEXT NOT NULL CHECK (status IN (
                'queued', 'running', 'completed', 'failed', 'cancelled', 'stale'
            )),
            attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
            active_attempt_id TEXT,
            report_path TEXT,
            report_hash TEXT CHECK (
                report_hash IS NULL OR (
                    length(report_hash) = 64 AND report_hash NOT GLOB '*[^0-9a-f]*'
                )
            ),
            result_json TEXT CHECK (result_json IS NULL OR json_valid(result_json)),
            error_code TEXT,
            diagnostic TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            started_at TEXT,
            completed_at TEXT,
            FOREIGN KEY (space, work_id)
                REFERENCES knowledge_project(space, id) ON DELETE CASCADE
        );
CREATE TABLE writing_consistency_check_attempt (
            id TEXT PRIMARY KEY CHECK (length(trim(id)) BETWEEN 1 AND 200),
            job_id TEXT NOT NULL REFERENCES writing_consistency_check_job(id) ON DELETE CASCADE,
            attempt_number INTEGER NOT NULL CHECK (attempt_number > 0),
            status TEXT NOT NULL CHECK (status IN (
                'running', 'completed', 'failed', 'interrupted'
            )),
            provider_receipts_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(provider_receipts_json)),
            error_code TEXT,
            started_at TEXT NOT NULL,
            completed_at TEXT,
            UNIQUE (job_id, attempt_number)
        );
CREATE TABLE knowledge_human_preservation (
            item_id TEXT PRIMARY KEY REFERENCES knowledge_item(id) ON DELETE RESTRICT,
            preservation_kind TEXT NOT NULL CHECK (preservation_kind IN (
                'human_record', 'preserved_human_dependency'
            )),
            origin_item_id TEXT NOT NULL,
            origin_version_id TEXT NOT NULL,
            origin_content_hash TEXT NOT NULL CHECK (length(origin_content_hash) = 64),
            origin_content_json TEXT NOT NULL CHECK (json_valid(origin_content_json)),
            migration_id TEXT NOT NULL,
            created_at TEXT NOT NULL
        );
CREATE TABLE embedding_read_cache_revision (
            singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
            revision INTEGER NOT NULL CHECK (revision >= 0)
        , knowledge_item_revision INTEGER NOT NULL DEFAULT 0
            CHECK (knowledge_item_revision >= 0), query_reuse_revision INTEGER NOT NULL DEFAULT 0
        CHECK (query_reuse_revision >= 0));
CREATE TABLE writing_narrative_order_state (
            space TEXT NOT NULL DEFAULT 'writing' CHECK (space = 'writing'),
            work_id TEXT NOT NULL,
            branch_id TEXT NOT NULL CHECK (length(trim(branch_id)) BETWEEN 1 AND 120),
            current_revision INTEGER NOT NULL CHECK (current_revision > 0),
            updated_at TEXT NOT NULL,
            PRIMARY KEY (space, work_id, branch_id),
            FOREIGN KEY (space, work_id)
                REFERENCES knowledge_project(space, id) ON DELETE CASCADE
        );
CREATE TABLE writing_narrative_order_revision (
            space TEXT NOT NULL DEFAULT 'writing' CHECK (space = 'writing'),
            work_id TEXT NOT NULL,
            branch_id TEXT NOT NULL CHECK (length(trim(branch_id)) BETWEEN 1 AND 120),
            revision INTEGER NOT NULL CHECK (revision > 0),
            manifest_hash TEXT NOT NULL CHECK (
                length(manifest_hash) = 64 AND manifest_hash NOT GLOB '*[^0-9a-f]*'
            ),
            is_complete INTEGER NOT NULL CHECK (is_complete IN (0, 1)),
            created_at TEXT NOT NULL,
            PRIMARY KEY (space, work_id, branch_id, revision),
            UNIQUE (space, work_id, branch_id, manifest_hash),
            FOREIGN KEY (space, work_id)
                REFERENCES knowledge_project(space, id) ON DELETE CASCADE
        );
CREATE TABLE writing_narrative_order_entry (
            space TEXT NOT NULL DEFAULT 'writing' CHECK (space = 'writing'),
            work_id TEXT NOT NULL,
            branch_id TEXT NOT NULL,
            revision INTEGER NOT NULL CHECK (revision > 0),
            chapter_id TEXT NOT NULL CHECK (length(trim(chapter_id)) BETWEEN 1 AND 200),
            ordinal INTEGER NOT NULL CHECK (ordinal > 0),
            adopted_artifact_id TEXT,
            adopted_revision INTEGER,
            adopted_hash TEXT CHECK (
                adopted_hash IS NULL OR (
                    length(adopted_hash) = 64 AND adopted_hash NOT GLOB '*[^0-9a-f]*'
                )
            ),
            head_version INTEGER,
            lifecycle_event_id INTEGER,
            CHECK (
                (adopted_artifact_id IS NULL AND adopted_revision IS NULL
                    AND adopted_hash IS NULL AND head_version IS NULL
                    AND lifecycle_event_id IS NULL)
                OR (adopted_artifact_id IS NOT NULL AND adopted_revision IS NOT NULL
                    AND adopted_hash IS NOT NULL AND head_version IS NOT NULL
                    AND lifecycle_event_id IS NOT NULL)
            ),
            PRIMARY KEY (space, work_id, branch_id, revision, chapter_id),
            UNIQUE (space, work_id, branch_id, revision, ordinal),
            FOREIGN KEY (space, work_id, branch_id, revision)
                REFERENCES writing_narrative_order_revision(space, work_id, branch_id, revision)
                ON DELETE CASCADE
        );
CREATE TABLE writing_base_work_reference (
            work_space TEXT NOT NULL DEFAULT 'writing' CHECK (work_space = 'writing'),
            work_id TEXT NOT NULL,
            base_space TEXT NOT NULL DEFAULT 'writing'
                CHECK (base_space IN ('writing', 'learning')),
            base_work_id TEXT NOT NULL,
            base_branch_id TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            PRIMARY KEY (work_id),
            CHECK (work_space != base_space OR work_id != base_work_id),
            CHECK (
                (base_space = 'writing' AND base_branch_id IS NOT NULL
                    AND length(trim(base_branch_id)) BETWEEN 1 AND 120)
                OR (base_space = 'learning' AND base_branch_id IS NULL)
            ),
            FOREIGN KEY (work_space, work_id)
                REFERENCES knowledge_project(space, id) ON DELETE RESTRICT,
            FOREIGN KEY (base_space, base_work_id)
                REFERENCES knowledge_project(space, id) ON DELETE RESTRICT
        );
CREATE TABLE "writing_base_source_reference" (
            work_id TEXT NOT NULL
                REFERENCES writing_base_work_reference(work_id) ON DELETE CASCADE,
            source_id TEXT NOT NULL REFERENCES source(id) ON DELETE RESTRICT,
            created_at TEXT NOT NULL,
            PRIMARY KEY (work_id, source_id)
        );
CREATE TABLE "writing_base_scope_reference" (
            work_id TEXT NOT NULL
                REFERENCES writing_base_work_reference(work_id) ON DELETE CASCADE,
            folder_id TEXT REFERENCES knowledge_folder(id) ON DELETE CASCADE,
            created_at TEXT NOT NULL
        );
CREATE TABLE embedding_projection_scope_backfill (
            route_fingerprint TEXT NOT NULL,
            scope_key TEXT NOT NULL,
            scope_json TEXT NOT NULL,
            cursor_target_id TEXT NOT NULL DEFAULT '',
            upper_bound_target_id TEXT NOT NULL DEFAULT '',
            scanned_chunks INTEGER NOT NULL DEFAULT 0 CHECK (scanned_chunks >= 0),
            status TEXT NOT NULL DEFAULT 'pending'
                CHECK (status IN ('pending', 'completed')),
            updated_at TEXT NOT NULL,
            PRIMARY KEY (route_fingerprint, scope_key)
        );
CREATE TABLE knowledge_project_count_summary (
            space TEXT NOT NULL CHECK (space IN ('learning', 'writing')),
            work_id TEXT NOT NULL,
            knowledge_count INTEGER,
            dirty INTEGER NOT NULL DEFAULT 1 CHECK (dirty IN (0, 1)),
            updated_at TEXT,
            PRIMARY KEY (space, work_id),
            FOREIGN KEY (space, work_id)
                REFERENCES knowledge_project(space, id) ON DELETE CASCADE,
            CHECK (
                (dirty = 1 AND knowledge_count IS NULL AND updated_at IS NULL)
                OR (dirty = 0 AND knowledge_count IS NOT NULL AND updated_at IS NOT NULL)
            ),
            CHECK (knowledge_count IS NULL OR knowledge_count >= 0)
        );
CREATE TABLE knowledge_parse_stage_attempt (
            id TEXT PRIMARY KEY,
            batch_id TEXT NOT NULL,
            phase TEXT NOT NULL CHECK (
                phase IN ('check', 'identity_resolution', 'event_resolution')
            ),
            group_ref TEXT NOT NULL CHECK (length(trim(group_ref)) > 0),
            attempt INTEGER NOT NULL CHECK (attempt > 0),
            route_index INTEGER NOT NULL CHECK (route_index >= 0),
            input_hash TEXT NOT NULL CHECK (length(input_hash) = 64),
            prompt_hash TEXT NOT NULL CHECK (length(prompt_hash) = 64),
            provider_model TEXT NOT NULL CHECK (length(trim(provider_model)) > 0),
            status TEXT NOT NULL CHECK (
                status IN ('requested', 'received', 'validated', 'failed', 'stale')
            ),
            source_pins_json TEXT NOT NULL CHECK (json_valid(source_pins_json)),
            manifest_pin_json TEXT CHECK (
                manifest_pin_json IS NULL OR json_valid(manifest_pin_json)
            ),
            manifest_pin_hash TEXT,
            candidate_refs_json TEXT NOT NULL CHECK (json_valid(candidate_refs_json)),
            request_json TEXT NOT NULL CHECK (json_valid(request_json)),
            response_text TEXT,
            response_hash TEXT,
            usage_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(usage_json)),
            validation_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(validation_json)),
            created_at TEXT NOT NULL,
            response_received_at TEXT,
            finished_at TEXT,
            UNIQUE (batch_id, phase, group_ref, attempt, route_index),
            CHECK (
                manifest_pin_json IS NULL
                OR (manifest_pin_hash IS NOT NULL AND length(manifest_pin_hash) = 64)
            ),
            CHECK (response_text IS NULL OR response_hash IS NOT NULL),
            CHECK (status != 'requested' OR response_text IS NULL),
            CHECK (status NOT IN ('received', 'validated') OR response_text IS NOT NULL),
            CHECK (status NOT IN ('validated', 'failed', 'stale') OR finished_at IS NOT NULL)
        );
CREATE TABLE embedding_projection_job (
            id TEXT PRIMARY KEY,
            target_type TEXT NOT NULL CHECK (target_type IN ('chunk', 'knowledge_item')),
            target_id TEXT NOT NULL,
            content_hash TEXT NOT NULL CHECK (length(content_hash) = 64),
            route_fingerprint TEXT NOT NULL DEFAULT '',
            provider TEXT NOT NULL DEFAULT '',
            model_id TEXT NOT NULL DEFAULT '',
            status TEXT NOT NULL CHECK (
                status IN ('pending', 'running', 'complete', 'failed', 'superseded')
            ),
            attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
            error_text TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            UNIQUE(target_type, target_id, content_hash, route_fingerprint)
        );
CREATE TABLE embedding_projection_candidate_backfill (
            scope_key TEXT PRIMARY KEY,
            route_fingerprint TEXT NOT NULL,
            scope_json TEXT NOT NULL,
            cursor_item_id TEXT NOT NULL DEFAULT '',
            upper_bound_item_id TEXT NOT NULL DEFAULT '',
            scanned_candidates INTEGER NOT NULL DEFAULT 0 CHECK (scanned_candidates >= 0),
            status TEXT NOT NULL DEFAULT 'pending'
                CHECK (status IN ('pending', 'completed', 'superseded')),
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
CREATE TABLE knowledge_candidate_embedding_enqueue_receipt (
            publication_id TEXT PRIMARY KEY,
            request_hash TEXT NOT NULL CHECK (length(request_hash) = 64),
            source_ids_json TEXT NOT NULL,
            source_snapshot_pins_json TEXT NOT NULL DEFAULT '[]',
            route_fingerprint TEXT,
            status TEXT NOT NULL CHECK (
                status IN ('pending', 'queued', 'failed', 'unavailable', 'outside_automatic_scope')
            ),
            result_json TEXT,
            error_text TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
CREATE TABLE "knowledge_parse_batch" (
            id TEXT PRIMARY KEY,
            space TEXT NOT NULL CHECK (space IN ('learning', 'writing')),
            work_id TEXT,
            folder_id TEXT,
            branch_id TEXT,
            max_concurrency INTEGER NOT NULL CHECK (max_concurrency BETWEEN 1 AND 20),
            force_reparse INTEGER NOT NULL CHECK (force_reparse IN (0, 1)),
            status TEXT NOT NULL CHECK (status IN (
                'queued', 'running', 'completed', 'partial', 'failed'
            )),
            total_sources INTEGER NOT NULL CHECK (total_sources > 0),
            summary_json TEXT NOT NULL DEFAULT '{}',
            diagnostic TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        , client_batch_id TEXT
            CHECK (client_batch_id IS NULL OR (
                length(client_batch_id) BETWEEN 1 AND 128 AND trim(client_batch_id) = client_batch_id
            )), client_request_hash TEXT
            CHECK (client_request_hash IS NULL OR length(client_request_hash) = 64), requested_work_id TEXT, requested_manifest_pin_json TEXT
            CHECK (requested_manifest_pin_json IS NULL OR json_valid(requested_manifest_pin_json)), completion_goal TEXT NOT NULL
            DEFAULT 'full_graph' CHECK (completion_goal IN ('reviewed_claims', 'full_graph')), grouping_policy TEXT NOT NULL
            DEFAULT 'paragraph' CHECK (grouping_policy IN ('paragraph', 'whole_short_source')));
CREATE TABLE knowledge_dialogue_utterance (
            id TEXT NOT NULL,
            annotation_set_id TEXT NOT NULL
                REFERENCES knowledge_dialogue_annotation_set(id) ON DELETE CASCADE,
            dialogue_ref TEXT NOT NULL,
            start_offset INTEGER NOT NULL CHECK (start_offset >= 0),
            end_offset INTEGER NOT NULL CHECK (end_offset > start_offset),
            quote TEXT NOT NULL CHECK (length(quote) > 0),
            quote_hash TEXT NOT NULL CHECK (length(quote_hash) = 64),
            quote_kind TEXT NOT NULL CHECK (quote_kind IN ('speech', 'quoted_text', 'uncertain')),
            speaker_status TEXT NOT NULL CHECK (
                speaker_status IN ('identified', 'unresolved', 'not_applicable')
            ),
            speaker_entity_item_id TEXT,
            speaker_candidate_item_id TEXT,
            speaker_identity_group_id TEXT,
            span_refs_json TEXT NOT NULL CHECK (json_valid(span_refs_json)),
            speaker_evidence_refs_json TEXT NOT NULL CHECK (json_valid(speaker_evidence_refs_json)),
            narrative_position_json TEXT CHECK (
                narrative_position_json IS NULL OR json_valid(narrative_position_json)
            ),
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            PRIMARY KEY(annotation_set_id, id),
            UNIQUE(annotation_set_id, start_offset, end_offset, quote_hash),
            CHECK (
                (quote_kind = 'speech' AND speaker_status IN ('identified', 'unresolved'))
                OR (quote_kind = 'quoted_text' AND speaker_status = 'not_applicable')
                OR (quote_kind = 'uncertain' AND speaker_status = 'unresolved')
            ),
            CHECK (
                (speaker_status = 'identified' AND speaker_entity_item_id IS NOT NULL
                 AND speaker_candidate_item_id IS NOT NULL)
                OR (speaker_status != 'identified' AND speaker_entity_item_id IS NULL
                    AND speaker_candidate_item_id IS NULL AND speaker_identity_group_id IS NULL)
            )
        );
CREATE VIRTUAL TABLE knowledge_dialogue_utterance_fts USING fts5(
            utterance_id UNINDEXED,
            quote,
            tokenize = 'unicode61'
        );
CREATE TABLE knowledge_dialogue_annotation_set (
            id TEXT PRIMARY KEY,
            receipt_id TEXT NOT NULL REFERENCES knowledge_parse_receipt(id) ON DELETE CASCADE,
            generation INTEGER NOT NULL CHECK (generation > 0),
            parse_batch_id TEXT REFERENCES knowledge_parse_batch(id) ON DELETE CASCADE,
            space TEXT NOT NULL CHECK (space IN ('learning', 'writing')),
            scope_work_id TEXT,
            physical_work_id TEXT,
            branch_id TEXT,
            source_id TEXT NOT NULL REFERENCES source(id) ON DELETE CASCADE,
            snapshot_id TEXT NOT NULL REFERENCES source_snapshot(id) ON DELETE CASCADE,
            content_hash TEXT NOT NULL CHECK (length(content_hash) = 64),
            utterance_count INTEGER NOT NULL CHECK (utterance_count >= 0),
            annotation_hash TEXT NOT NULL CHECK (length(annotation_hash) = 64),
            input_annotation_hash TEXT NOT NULL CHECK (length(input_annotation_hash) = 64),
            dialogue_review_proof_json TEXT CHECK (
                dialogue_review_proof_json IS NULL OR json_valid(dialogue_review_proof_json)
            ),
            dialogue_review_status TEXT NOT NULL DEFAULT 'pending' CHECK (
                dialogue_review_status IN ('pending', 'passed', 'empty')
            ),
            status TEXT NOT NULL CHECK (status IN ('candidate', 'published', 'superseded')),
            annotation_revision INTEGER NOT NULL DEFAULT 1 CHECK (annotation_revision > 0),
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            UNIQUE(receipt_id, generation, annotation_revision),
            CHECK (
                (space = 'learning' AND branch_id IS NULL)
                OR (space = 'writing' AND scope_work_id IS NOT NULL AND branch_id IS NOT NULL)
            ),
            CHECK (
                status != 'published'
                OR (dialogue_review_status IN ('passed', 'empty')
                    AND dialogue_review_proof_json IS NOT NULL)
            )
        );
CREATE TABLE knowledge_parse_submission (
            id TEXT PRIMARY KEY,
            client_batch_id TEXT NOT NULL,
            scope_key TEXT NOT NULL,
            space TEXT NOT NULL CHECK (space IN ('learning', 'writing')),
            work_id TEXT,
            request_hash TEXT NOT NULL CHECK (length(request_hash) = 64),
            request_json TEXT NOT NULL CHECK (json_valid(request_json)),
            initial_failures_json TEXT NOT NULL CHECK (json_valid(initial_failures_json)),
            total_sources INTEGER NOT NULL CHECK (total_sources >= 0),
            status TEXT NOT NULL CHECK (
                status IN ('materializing', 'accepted', 'partial', 'failed')
            ),
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            UNIQUE (space, scope_key, client_batch_id)
        );
CREATE TABLE knowledge_parse_submission_child (
            id TEXT PRIMARY KEY,
            submission_id TEXT NOT NULL REFERENCES knowledge_parse_submission(id),
            ordinal INTEGER NOT NULL CHECK (ordinal >= 0),
            client_batch_id TEXT NOT NULL UNIQUE,
            request_json TEXT NOT NULL CHECK (json_valid(request_json)),
            status TEXT NOT NULL CHECK (status IN ('pending', 'accepted', 'failed')),
            batch_id TEXT,
            failure_json TEXT CHECK (failure_json IS NULL OR json_valid(failure_json)),
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL, queue_release_json TEXT CHECK (
            queue_release_json IS NULL OR json_valid(queue_release_json)
        ),
            UNIQUE (submission_id, ordinal),
            CHECK (
                (status = 'pending' AND batch_id IS NULL AND failure_json IS NULL)
                OR (status = 'accepted' AND batch_id IS NOT NULL AND failure_json IS NULL)
                OR (status = 'failed' AND batch_id IS NULL AND failure_json IS NOT NULL)
            )
        );
CREATE TABLE "knowledge_graph_relation_reference" (
            candidate_item_id TEXT NOT NULL
                REFERENCES knowledge_item(id) ON DELETE CASCADE,
            candidate_version_id TEXT NOT NULL
                REFERENCES knowledge_version(id) ON DELETE CASCADE,
            space TEXT NOT NULL CHECK (space IN ('learning','writing')),
            work_id TEXT,
            reference_kind TEXT NOT NULL CHECK (reference_kind IN ('identity_group','entity_ref')),
            reference_id TEXT NOT NULL CHECK (length(trim(reference_id)) > 0),
            relation_role TEXT NOT NULL CHECK (relation_role IN (
                'subject','target','asserted_by','observed_by','holder','audience',
                'entity_member'
            )),
            PRIMARY KEY(candidate_item_id, reference_kind, reference_id, relation_role),
            CHECK ((space='learning') OR (space='writing' AND work_id IS NOT NULL)),
            FOREIGN KEY (space, work_id) REFERENCES knowledge_project(space,id) ON DELETE RESTRICT
        ) WITHOUT ROWID;
CREATE TABLE knowledge_parse_processing_unit (
            id TEXT PRIMARY KEY,
            batch_id TEXT NOT NULL REFERENCES knowledge_parse_batch(id) ON DELETE CASCADE,
            phase TEXT NOT NULL CHECK (phase IN ('identity_resolution')),
            folder_id TEXT,
            group_ref TEXT NOT NULL CHECK (length(trim(group_ref)) > 0),
            input_hash TEXT NOT NULL CHECK (length(input_hash) = 64),
            prompt_hash TEXT NOT NULL CHECK (length(prompt_hash) = 64),
            input_fingerprint TEXT NOT NULL CHECK (length(input_fingerprint) = 64),
            source_pins_json TEXT NOT NULL CHECK (json_valid(source_pins_json)),
            candidate_refs_json TEXT NOT NULL CHECK (json_valid(candidate_refs_json)),
            manifest_pin_json TEXT CHECK (
                manifest_pin_json IS NULL OR json_valid(manifest_pin_json)
            ),
            execution_status TEXT NOT NULL CHECK (
                execution_status IN ('prepared', 'running', 'failed', 'completed', 'stale', 'superseded')
            ),
            model_status TEXT NOT NULL CHECK (
                model_status IN ('not_started', 'requested', 'response_saved', 'validated')
            ),
            attempt_count INTEGER NOT NULL CHECK (attempt_count > 0),
            attempt_ids_json TEXT NOT NULL CHECK (json_valid(attempt_ids_json)),
            outcome_json TEXT NOT NULL CHECK (json_valid(outcome_json)),
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            UNIQUE (batch_id, phase, input_fingerprint)
        );
CREATE TABLE knowledge_reviewed_claim_publication (
            id TEXT PRIMARY KEY,
            basis TEXT NOT NULL CHECK (basis = 'reviewed_claim'),
            batch_id TEXT NOT NULL,
            ordinal INTEGER NOT NULL CHECK (ordinal >= 0),
            space TEXT NOT NULL CHECK (space IN ('learning', 'writing')),
            work_id TEXT,
            branch_id TEXT,
            source_id TEXT NOT NULL REFERENCES source(id),
            snapshot_id TEXT NOT NULL REFERENCES source_snapshot(id),
            parse_receipt_id TEXT NOT NULL REFERENCES knowledge_parse_receipt(id),
            generation INTEGER NOT NULL CHECK (generation > 0),
            candidate_item_id TEXT NOT NULL REFERENCES knowledge_item(id),
            candidate_version_id TEXT NOT NULL REFERENCES knowledge_version(id),
            check_input_hash TEXT NOT NULL CHECK (length(check_input_hash) = 64),
            check_result_hash TEXT NOT NULL CHECK (length(check_result_hash) = 64),
            proof_json TEXT NOT NULL CHECK (json_valid(proof_json)),
            created_at TEXT NOT NULL,
            UNIQUE (batch_id, ordinal, candidate_item_id, candidate_version_id),
            UNIQUE (id, candidate_item_id, candidate_version_id),
            FOREIGN KEY (batch_id, ordinal)
                REFERENCES knowledge_parse_batch_item(batch_id, ordinal)
                ON DELETE CASCADE,
            CHECK ((space = 'learning')
                OR (space = 'writing' AND work_id IS NOT NULL))
        );
CREATE TABLE "knowledge_claim_base_revision" (
        id TEXT PRIMARY KEY,
        item_id TEXT NOT NULL REFERENCES knowledge_item(id) ON DELETE RESTRICT,
        revision INTEGER NOT NULL CHECK (revision > 0),
        space TEXT NOT NULL CHECK (space IN ('learning', 'writing')),
        work_id TEXT,
        content_hash TEXT NOT NULL CHECK (length(content_hash) = 64),
        content_json TEXT NOT NULL CHECK (json_valid(content_json)),
        created_at TEXT NOT NULL,
        UNIQUE(item_id, revision),
        UNIQUE(item_id, content_hash),
        UNIQUE(id, item_id),
        CHECK (space != 'writing' OR work_id IS NOT NULL)
    );
CREATE TABLE "knowledge_claim_interpretation" (
        id TEXT PRIMARY KEY,
        item_id TEXT NOT NULL REFERENCES knowledge_item(id) ON DELETE RESTRICT,
        component_kind TEXT NOT NULL CHECK (component_kind IN (
            'identity', 'review', 'typed_event', 'typed_quantity', 'typed_rule',
            'typed_instance', 'proposition_resolution'
        )),
        revision INTEGER NOT NULL CHECK (revision > 0),
        space TEXT NOT NULL CHECK (space IN ('learning', 'writing')),
        work_id TEXT,
        content_hash TEXT NOT NULL CHECK (length(content_hash) = 64),
        content_json TEXT NOT NULL CHECK (json_valid(content_json)),
        created_at TEXT NOT NULL,
        UNIQUE(item_id, component_kind, revision),
        UNIQUE(item_id, component_kind, content_hash),
        UNIQUE(id, item_id, component_kind),
        CHECK (space != 'writing' OR work_id IS NOT NULL)
    );
CREATE TABLE "knowledge_claim_version_component" (
        knowledge_version_id TEXT PRIMARY KEY
            REFERENCES knowledge_version(id) ON DELETE RESTRICT,
        item_id TEXT NOT NULL REFERENCES knowledge_item(id) ON DELETE RESTRICT,
        space TEXT NOT NULL CHECK (space IN ('learning', 'writing')),
        work_id TEXT,
        base_revision_id TEXT NOT NULL,
        interpretation_refs_json TEXT NOT NULL CHECK (json_valid(interpretation_refs_json)),
        evidence_refs_json TEXT NOT NULL CHECK (json_valid(evidence_refs_json)),
        evidence_hash TEXT NOT NULL CHECK (length(evidence_hash) = 64),
        composed_content_hash TEXT NOT NULL CHECK (length(composed_content_hash) = 64),
        scope_verified INTEGER NOT NULL CHECK (scope_verified IN (0, 1)),
        scope_diagnostics_json TEXT NOT NULL CHECK (json_valid(scope_diagnostics_json)),
        created_at TEXT NOT NULL,
        UNIQUE(knowledge_version_id, item_id),
        FOREIGN KEY (base_revision_id, item_id)
            REFERENCES "knowledge_claim_base_revision"(id, item_id) ON DELETE RESTRICT,
        CHECK (space != 'writing' OR work_id IS NOT NULL)
    );
CREATE TABLE knowledge_item_retirement_authorization (
            item_id TEXT PRIMARY KEY REFERENCES knowledge_item(id) ON DELETE CASCADE,
            owner_kind TEXT NOT NULL CHECK (owner_kind IN (
                'parse_folder_clear', 'source_purge', 'project_delete'
            )),
            space TEXT NOT NULL CHECK (space IN ('learning', 'writing')),
            work_id TEXT,
            retired_at TEXT NOT NULL,
            CHECK (space != 'writing' OR work_id IS NOT NULL)
        );
CREATE TABLE knowledge_reviewed_claim_source_retirement_authorization (
            publication_id TEXT PRIMARY KEY,
            owner_kind TEXT NOT NULL CHECK (owner_kind = 'source_purge'),
            candidate_item_id TEXT NOT NULL REFERENCES knowledge_item(id) ON DELETE RESTRICT,
            source_id TEXT NOT NULL REFERENCES source(id) ON DELETE RESTRICT,
            snapshot_id TEXT NOT NULL REFERENCES source_snapshot(id) ON DELETE RESTRICT,
            space TEXT NOT NULL CHECK (space IN ('learning', 'writing')),
            work_id TEXT,
            authorized_at TEXT NOT NULL,
            CHECK (space != 'writing' OR work_id IS NOT NULL)
        );
CREATE TABLE knowledge_query_review_receipt (
            id TEXT PRIMARY KEY CHECK (length(id) = 64),
            space TEXT NOT NULL CHECK (space IN ('learning', 'writing')),
            work_id TEXT,
            branch_id TEXT,
            provider_model TEXT NOT NULL CHECK (length(trim(provider_model)) > 0),
            model_input_sha256 TEXT NOT NULL CHECK (length(model_input_sha256) = 64),
            prompt_sha256 TEXT NOT NULL CHECK (length(prompt_sha256) = 64),
            response_sha256 TEXT NOT NULL CHECK (length(response_sha256) = 64),
            requirement_ids_json TEXT NOT NULL CHECK (json_valid(requirement_ids_json)),
            scope_pins_json TEXT NOT NULL CHECK (json_valid(scope_pins_json)),
            proof_json TEXT NOT NULL CHECK (json_valid(proof_json)),
            status TEXT NOT NULL CHECK (status IN ('pending', 'published', 'failed')),
            failure_code TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            CHECK (space = 'learning' OR (space = 'writing' AND work_id IS NOT NULL)),
            CHECK ((status = 'failed') = (failure_code IS NOT NULL))
        );
CREATE TABLE knowledge_query_reviewed_claim_publication (
            id TEXT PRIMARY KEY CHECK (length(id) = 64),
            basis TEXT NOT NULL CHECK (basis = 'query_reviewed_claim'),
            receipt_id TEXT NOT NULL REFERENCES knowledge_query_review_receipt(id) ON DELETE RESTRICT,
            claim_ordinal INTEGER NOT NULL CHECK (claim_ordinal >= 0),
            space TEXT NOT NULL CHECK (space IN ('learning', 'writing')),
            work_id TEXT,
            branch_id TEXT,
            candidate_item_id TEXT NOT NULL REFERENCES knowledge_item(id) ON DELETE RESTRICT,
            candidate_version_id TEXT NOT NULL REFERENCES knowledge_version(id) ON DELETE RESTRICT,
            claim_hash TEXT NOT NULL CHECK (length(claim_hash) = 64),
            claim_json TEXT NOT NULL CHECK (json_valid(claim_json)),
            evidence_refs_json TEXT NOT NULL CHECK (json_valid(evidence_refs_json)),
            created_at TEXT NOT NULL,
            UNIQUE(receipt_id, claim_ordinal),
            UNIQUE(receipt_id, claim_hash),
            CHECK (space = 'learning' OR (space = 'writing' AND work_id IS NOT NULL))
        );
CREATE TABLE knowledge_query_result_cache (
            cache_key TEXT PRIMARY KEY,
            kind TEXT NOT NULL CHECK (kind IN ('plan', 'execution', 'answer')),
            dataset_revision TEXT NOT NULL,
            payload_json TEXT NOT NULL CHECK (json_valid(payload_json)),
            created_at TEXT NOT NULL
        );
CREATE TABLE knowledge_query_navigation (
            id TEXT PRIMARY KEY,
            scope_hash TEXT NOT NULL,
            subject TEXT NOT NULL,
            attribute TEXT,
            evidence_json TEXT NOT NULL CHECK (json_valid(evidence_json)),
            created_at TEXT NOT NULL
        );
CREATE TABLE source_record_history (
            source_id TEXT NOT NULL REFERENCES source(id) ON DELETE CASCADE,
            edit_revision INTEGER NOT NULL CHECK (edit_revision > 0),
            snapshot_id TEXT REFERENCES source_snapshot(id) ON DELETE CASCADE,
            title TEXT NOT NULL,
            source_uri TEXT,
            space TEXT NOT NULL,
            work_id TEXT,
            folder_id TEXT,
            deleted_at TEXT,
            document_metadata_json TEXT NOT NULL,
            recorded_at TEXT NOT NULL,
            PRIMARY KEY (source_id, edit_revision)
        );
CREATE TABLE assistant_conversation_undo (
            id TEXT PRIMARY KEY,
            conversation_id TEXT NOT NULL REFERENCES assistant_conversation(id),
            message_id TEXT NOT NULL,
            expected_revision INTEGER NOT NULL,
            client_operation_id TEXT NOT NULL UNIQUE,
            request_hash TEXT NOT NULL,
            mode TEXT NOT NULL CHECK (mode IN ('undo', 'edit')),
            status TEXT NOT NULL CHECK (status IN ('prepared', 'restoring', 'blocked', 'completed')),
            plan_json TEXT NOT NULL,
            pending_turn_json TEXT NOT NULL DEFAULT '{}',
            steps_json TEXT NOT NULL DEFAULT '{}',
            result_json TEXT NOT NULL DEFAULT '{}',
            error TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
CREATE TABLE conversation_write_fence (
            conversation_id TEXT NOT NULL,
            message_id TEXT NOT NULL,
            operation_id TEXT NOT NULL,
            created_at TEXT NOT NULL,
            PRIMARY KEY (conversation_id, message_id)
        );
CREATE TABLE conversation_effect (
            id TEXT PRIMARY KEY,
            conversation_id TEXT NOT NULL,
            message_id TEXT NOT NULL,
            run_id TEXT,
            space TEXT,
            work_id TEXT,
            domain TEXT NOT NULL,
            target_id TEXT NOT NULL,
            before_json TEXT,
            after_json TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'retracted')),
            retraction_operation_id TEXT,
            retraction_json TEXT NOT NULL DEFAULT '{}',
            created_at TEXT NOT NULL,
            retracted_at TEXT
        );
CREATE TABLE conversation_task_origin (
            task_kind TEXT NOT NULL,
            task_id TEXT NOT NULL,
            origin_json TEXT NOT NULL,
            PRIMARY KEY (task_kind, task_id)
        );
CREATE TABLE "creative_plan_section_state" (
            work_id TEXT NOT NULL CHECK (length(trim(work_id)) BETWEEN 1 AND 200),
            section_id TEXT NOT NULL CHECK (
                length(trim(section_id)) BETWEEN 1 AND 200 AND section_id = trim(section_id)
            ),
            folder_id TEXT REFERENCES knowledge_folder(id) ON DELETE SET NULL,
            updated_at TEXT NOT NULL,
            PRIMARY KEY (work_id, section_id)
        );
CREATE TABLE author_input_coverage (
        id TEXT PRIMARY KEY,
        work_id TEXT NOT NULL,
        source_json TEXT NOT NULL,
        original_hash TEXT NOT NULL,
        remaining_text TEXT NOT NULL,
        disposition TEXT NOT NULL,
        record_ids_json TEXT NOT NULL,
        resolution_id TEXT NOT NULL
    );
CREATE TABLE author_input_resolution (
        id TEXT PRIMARY KEY,
        work_id TEXT NOT NULL,
        input_json TEXT NOT NULL,
        response_json TEXT NOT NULL
