CREATE TRIGGER source_snapshot_no_update
        BEFORE UPDATE ON source_snapshot
        BEGIN
            SELECT RAISE(ABORT, 'source snapshots are immutable');
        END;
CREATE TRIGGER source_snapshot_no_delete
        BEFORE DELETE ON source_snapshot
        BEGIN
            SELECT RAISE(ABORT, 'source snapshots are immutable');
        END;
CREATE TRIGGER chunk_valid_range
        BEFORE INSERT ON chunk
        WHEN NEW.end_offset > (
                 SELECT length(content) FROM source_snapshot WHERE id = NEW.snapshot_id
             )
             OR NEW.end_offset - NEW.start_offset != length(NEW.text)
             OR substr(
                    (SELECT content FROM source_snapshot WHERE id = NEW.snapshot_id),
                    NEW.start_offset + 1,
                    NEW.end_offset - NEW.start_offset
                ) != NEW.text
        BEGIN
            SELECT RAISE(ABORT, 'chunk offsets do not match source snapshot text');
        END;
CREATE TRIGGER evidence_valid_range
        BEFORE INSERT ON evidence_span
        WHEN NEW.end_offset > (
                 SELECT length(content) FROM source_snapshot WHERE id = NEW.snapshot_id
             )
             OR (
                 NEW.chunk_id IS NOT NULL
                 AND NOT EXISTS (
                     SELECT 1 FROM chunk
                     WHERE id = NEW.chunk_id
                       AND snapshot_id = NEW.snapshot_id
                       AND start_offset <= NEW.start_offset
                       AND end_offset >= NEW.end_offset
                 )
             )
        BEGIN
            SELECT RAISE(ABORT, 'evidence span offsets do not match source snapshot');
        END;
CREATE TRIGGER knowledge_version_no_update
        BEFORE UPDATE ON knowledge_version
        BEGIN
            SELECT RAISE(ABORT, 'knowledge versions are append-only');
        END;
CREATE TRIGGER source_folder_scope_insert
        BEFORE INSERT ON source
        WHEN NEW.folder_id IS NOT NULL
             AND NOT EXISTS (
                 SELECT 1 FROM knowledge_folder AS f
                 WHERE f.id = NEW.folder_id
                   AND f.space = NEW.space
                   AND f.work_id IS NEW.work_id
             )
        BEGIN
            SELECT RAISE(ABORT, 'source folder is outside its knowledge scope');
        END;
CREATE TRIGGER source_folder_scope_update
        BEFORE UPDATE OF folder_id ON source
        WHEN NEW.folder_id IS NOT NULL
             AND NOT EXISTS (
                 SELECT 1 FROM knowledge_folder AS f
                 WHERE f.id = NEW.folder_id
                   AND f.space = NEW.space
                   AND f.work_id IS NEW.work_id
             )
        BEGIN
            SELECT RAISE(ABORT, 'source folder is outside its knowledge scope');
        END;
CREATE TRIGGER writing_learning_source_reference_insert_scope
        BEFORE INSERT ON writing_learning_source_reference
        WHEN NOT EXISTS (
                 SELECT 1 FROM knowledge_project AS p
                 WHERE p.id = NEW.work_id
                   AND p.space = 'writing'
                   AND p.status = 'active'
             )
             OR NOT EXISTS (
                 SELECT 1 FROM source AS s
                 WHERE s.id = NEW.source_id
                   AND s.space = 'learning'
                   AND s.deleted_at IS NULL
                   AND (s.work_id IS NULL OR EXISTS (
                       SELECT 1 FROM knowledge_project AS p
                       WHERE p.id = s.work_id
                         AND p.space = 'learning'
                         AND p.status = 'active'
                   ))
             )
        BEGIN
            SELECT RAISE(ABORT, 'reference must link a writing work to an active learning source');
        END;
CREATE TRIGGER writing_learning_source_reference_update_scope
        BEFORE UPDATE OF work_id, source_id ON writing_learning_source_reference
        WHEN NOT EXISTS (
                 SELECT 1 FROM knowledge_project AS p
                 WHERE p.id = NEW.work_id
                   AND p.space = 'writing'
                   AND p.status = 'active'
             )
             OR NOT EXISTS (
                 SELECT 1 FROM source AS s
                 WHERE s.id = NEW.source_id
                   AND s.space = 'learning'
                   AND s.deleted_at IS NULL
                   AND (s.work_id IS NULL OR EXISTS (
                       SELECT 1 FROM knowledge_project AS p
                       WHERE p.id = s.work_id
                         AND p.space = 'learning'
                         AND p.status = 'active'
                   ))
             )
        BEGIN
            SELECT RAISE(ABORT, 'reference must link a writing work to an active learning source');
        END;
CREATE TRIGGER source_current_snapshot_insert_scope
        BEFORE INSERT ON source_current_snapshot
        WHEN NOT EXISTS (
            SELECT 1 FROM source_snapshot AS ss
            WHERE ss.id = NEW.snapshot_id AND ss.source_id = NEW.source_id
        )
        BEGIN
            SELECT RAISE(ABORT, 'current snapshot must belong to its source');
        END;
CREATE TRIGGER source_current_snapshot_update_scope
        BEFORE UPDATE OF source_id, snapshot_id ON source_current_snapshot
        WHEN NOT EXISTS (
            SELECT 1 FROM source_snapshot AS ss
            WHERE ss.id = NEW.snapshot_id AND ss.source_id = NEW.source_id
        )
        BEGIN
            SELECT RAISE(ABORT, 'current snapshot must belong to its source');
        END;
CREATE TRIGGER source_section_valid_range
        BEFORE INSERT ON source_section
        WHEN NEW.end_offset > (
                 SELECT length(content) FROM source_snapshot WHERE id = NEW.snapshot_id
             )
             OR EXISTS (
                 SELECT 1 FROM source_section AS existing
                 WHERE existing.snapshot_id = NEW.snapshot_id
                   AND existing.sectioning_version = NEW.sectioning_version
                   AND NOT (
                       NEW.end_offset <= existing.start_offset
                       OR NEW.start_offset >= existing.end_offset
                   )
             )
        BEGIN
            SELECT RAISE(ABORT, 'source section offsets overlap or exceed the source snapshot');
        END;
CREATE TRIGGER source_section_no_update
        BEFORE UPDATE ON source_section
        BEGIN
            SELECT RAISE(ABORT, 'source sections are immutable');
        END;
CREATE TRIGGER source_section_no_delete
        BEFORE DELETE ON source_section
        BEGIN
            SELECT RAISE(ABORT, 'source sections are immutable');
        END;
CREATE TRIGGER knowledge_parse_receipt_insert_scope
        BEFORE INSERT ON knowledge_parse_receipt
        WHEN (
                 NEW.work_id IS NOT NULL
                 AND NOT EXISTS (
                     SELECT 1 FROM knowledge_project AS p
                     WHERE p.id = NEW.work_id
                       AND p.space = NEW.space
                       AND p.status = 'active'
                 )
             )
             OR NOT EXISTS (
                 SELECT 1 FROM source AS s
                 JOIN source_snapshot AS ss ON ss.source_id = s.id
                 WHERE s.id = NEW.source_id
                   AND s.space = NEW.space
                   AND s.work_id IS NEW.work_id
                   AND s.deleted_at IS NULL
                   AND ss.id = NEW.snapshot_id
             )
        BEGIN
            SELECT RAISE(ABORT, 'knowledge parse must match an active source snapshot scope');
        END;
CREATE TRIGGER knowledge_version_no_delete
        BEFORE DELETE ON knowledge_version
        BEGIN
            SELECT RAISE(ABORT, 'knowledge versions are append-only');
        END;
CREATE TRIGGER knowledge_parse_receipt_scope_immutable
        BEFORE UPDATE OF space, work_id, source_id, snapshot_id, branch_id,
                         prompt_hash, route_fingerprint, parser_version,
                         input_hash, generation
        ON knowledge_parse_receipt
        WHEN NEW.space IS NOT OLD.space
          OR NEW.work_id IS NOT OLD.work_id
          OR NEW.source_id IS NOT OLD.source_id
          OR NEW.snapshot_id IS NOT OLD.snapshot_id
          OR NEW.branch_id IS NOT OLD.branch_id
          OR NEW.prompt_hash IS NOT OLD.prompt_hash
          OR NEW.route_fingerprint IS NOT OLD.route_fingerprint
          OR NEW.parser_version IS NOT OLD.parser_version
          OR NEW.input_hash IS NOT OLD.input_hash
          OR NEW.generation IS NOT OLD.generation
        BEGIN
            SELECT RAISE(ABORT, 'knowledge parse receipt identity is immutable');
        END;
CREATE TRIGGER prose_detector_comparison_no_update
        BEFORE UPDATE ON prose_detector_comparison
        BEGIN
            SELECT RAISE(ABORT, 'prose detector comparisons are immutable');
        END;
CREATE TRIGGER prose_detector_comparison_no_delete
        BEFORE DELETE ON prose_detector_comparison
        BEGIN
            SELECT RAISE(ABORT, 'prose detector comparisons are immutable');
        END;
CREATE TRIGGER knowledge_source_ownership_transfer_insert_guard
        BEFORE INSERT ON knowledge_source_ownership_transfer
        WHEN NEW.status != 'applying'
          OR NEW.created_folder_count != -1
          OR NOT EXISTS (
              SELECT 1 FROM knowledge_project AS target
              WHERE target.id = NEW.target_work_id
                AND target.space = 'writing'
                AND target.status = 'active'
          )
          OR (
              NEW.source_work_id IS NOT NULL
              AND NOT EXISTS (
                  SELECT 1 FROM knowledge_project AS source_project
                  WHERE source_project.id = NEW.source_work_id
                    AND source_project.space = NEW.source_space
                    AND source_project.status = 'active'
              )
          )
        BEGIN
            SELECT RAISE(ABORT, 'ownership transfer receipts must begin as an active transaction');
        END;
CREATE TRIGGER knowledge_source_ownership_transfer_immutable
        BEFORE UPDATE OF operation_id, request_hash, expected_fingerprint,
                         source_space, source_work_id, target_work_id,
                         source_count, created_at
        ON knowledge_source_ownership_transfer
        WHEN NEW.operation_id IS NOT OLD.operation_id
          OR NEW.request_hash IS NOT OLD.request_hash
          OR NEW.expected_fingerprint IS NOT OLD.expected_fingerprint
          OR NEW.source_space IS NOT OLD.source_space
          OR NEW.source_work_id IS NOT OLD.source_work_id
          OR NEW.target_work_id IS NOT OLD.target_work_id
          OR NEW.source_count IS NOT OLD.source_count
          OR NEW.created_at IS NOT OLD.created_at
        BEGIN
            SELECT RAISE(ABORT, 'ownership transfer receipt identity is immutable');
        END;
CREATE TRIGGER knowledge_source_ownership_transfer_status_guard
        BEFORE UPDATE OF status ON knowledge_source_ownership_transfer
        WHEN OLD.status != 'applying' OR NEW.status != 'completed'
          OR OLD.created_folder_count != -1
          OR NEW.created_folder_count < 0
          OR (SELECT COUNT(*)
              FROM knowledge_source_ownership_transfer_item AS item
              WHERE item.operation_id = OLD.operation_id) != NEW.source_count
          OR EXISTS (
              SELECT 1
              FROM knowledge_source_ownership_transfer_item AS item
              JOIN source AS selected ON selected.id = item.source_id
              WHERE item.operation_id = OLD.operation_id
                AND (
                    selected.space != 'writing'
                    OR selected.work_id IS NOT item.target_work_id
                    OR selected.folder_id IS NOT item.target_folder_id
                    OR selected.identity_key IS NOT item.target_identity_key
                )
          )
        BEGIN
            SELECT RAISE(ABORT, 'ownership transfer cannot complete before every source is applied');
        END;
CREATE TRIGGER knowledge_source_ownership_transfer_folder_count_guard
        BEFORE UPDATE OF created_folder_count ON knowledge_source_ownership_transfer
        WHEN OLD.status != 'applying'
          OR NEW.status != 'completed'
          OR OLD.created_folder_count != -1
          OR NEW.created_folder_count < 0
        BEGIN
            SELECT RAISE(ABORT, 'ownership transfer folder count is immutable after completion');
        END;
CREATE TRIGGER knowledge_source_ownership_transfer_no_delete
        BEFORE DELETE ON knowledge_source_ownership_transfer
        BEGIN
            SELECT RAISE(ABORT, 'ownership transfer receipts are retained');
        END;
CREATE TRIGGER knowledge_source_ownership_transfer_item_no_update
        BEFORE UPDATE ON knowledge_source_ownership_transfer_item
        BEGIN
            SELECT RAISE(ABORT, 'ownership transfer items are immutable');
        END;
CREATE TRIGGER knowledge_source_ownership_transfer_item_no_delete
        BEFORE DELETE ON knowledge_source_ownership_transfer_item
        BEGIN
            SELECT RAISE(ABORT, 'ownership transfer items are retained');
        END;
CREATE TRIGGER knowledge_source_ownership_transfer_item_insert_guard
        BEFORE INSERT ON knowledge_source_ownership_transfer_item
        WHEN NOT EXISTS (
                 SELECT 1
                 FROM knowledge_source_ownership_transfer AS operation
                 JOIN source AS selected ON selected.id = NEW.source_id
                 JOIN knowledge_project AS target
                   ON target.id = NEW.target_work_id
                  AND target.space = 'writing'
                  AND target.status = 'active'
                 WHERE operation.operation_id = NEW.operation_id
                   AND operation.status = 'applying'
                   AND operation.source_space = NEW.source_space
                   AND operation.source_work_id IS NEW.source_work_id
                   AND operation.target_work_id = NEW.target_work_id
                   AND selected.space = NEW.source_space
                   AND selected.work_id IS NEW.source_work_id
                   AND selected.deleted_at IS NULL
                   AND (
                       NEW.target_folder_id IS NULL
                       OR EXISTS (
                           SELECT 1 FROM knowledge_folder AS folder
                           WHERE folder.id = NEW.target_folder_id
                             AND folder.space = 'writing'
                             AND folder.work_id = NEW.target_work_id
                       )
                   )
             )
        BEGIN
            SELECT RAISE(ABORT, 'ownership transfer item does not match an active transfer');
        END;
CREATE TRIGGER source_scope_immutable
        BEFORE UPDATE OF space, work_id ON source
        WHEN NEW.space != OLD.space OR NEW.work_id IS NOT OLD.work_id
        BEGIN
            SELECT CASE WHEN NOT EXISTS (
                SELECT 1
                FROM knowledge_source_ownership_transfer_item AS item
                JOIN knowledge_source_ownership_transfer AS operation
                  ON operation.operation_id = item.operation_id
                WHERE operation.status = 'applying'
                  AND item.source_id = OLD.id
                  AND item.source_space = OLD.space
                  AND item.source_work_id IS OLD.work_id
                  AND NEW.space = 'writing'
                  AND item.target_work_id IS NEW.work_id
                  AND item.target_folder_id IS NEW.folder_id
                  AND item.target_identity_key = NEW.identity_key
                  AND NEW.id IS OLD.id
                  AND NEW.title IS OLD.title
                  AND NEW.source_uri IS OLD.source_uri
                  AND NEW.deleted_at IS OLD.deleted_at
                  AND NEW.document_metadata_json IS OLD.document_metadata_json
                  AND NEW.created_at IS OLD.created_at
            ) THEN RAISE(ABORT, 'source scope is immutable outside an ownership transfer') END;
        END;
CREATE TRIGGER knowledge_card_folder_summary_candidate_insert
