        BEFORE INSERT ON writing_base_work_reference
        WHEN NOT EXISTS (
                 SELECT 1 FROM knowledge_project AS writing_work
                 WHERE writing_work.id = NEW.work_id
                   AND writing_work.space = 'writing'
                   AND writing_work.status = 'active'
