CREATE TRIGGER knowledge_dialogue_utterance_published_immutable_update
        BEFORE UPDATE ON knowledge_dialogue_utterance
        WHEN (SELECT status FROM knowledge_dialogue_annotation_set
              WHERE id=OLD.annotation_set_id) = 'published'
        BEGIN
            SELECT RAISE(ABORT, 'published dialogue annotations are immutable');
        END;
CREATE TRIGGER knowledge_dialogue_utterance_published_immutable_delete
        BEFORE DELETE ON knowledge_dialogue_utterance
        WHEN (SELECT status FROM knowledge_dialogue_annotation_set
              WHERE id=OLD.annotation_set_id) = 'published'
        BEGIN
            SELECT RAISE(ABORT, 'published dialogue annotations are immutable');
        END;
CREATE TRIGGER knowledge_dialogue_utterance_fts_insert
        AFTER INSERT ON knowledge_dialogue_utterance
        WHEN (SELECT status FROM knowledge_dialogue_annotation_set WHERE id = NEW.annotation_set_id)
             = 'published'
        BEGIN
            INSERT INTO knowledge_dialogue_utterance_fts(rowid, utterance_id, quote)
            VALUES (NEW.rowid, NEW.id, NEW.quote);
        END;
CREATE TRIGGER knowledge_dialogue_utterance_fts_update
        AFTER UPDATE ON knowledge_dialogue_utterance
        BEGIN
            DELETE FROM knowledge_dialogue_utterance_fts WHERE rowid = OLD.rowid;
            INSERT INTO knowledge_dialogue_utterance_fts(rowid, utterance_id, quote)
            SELECT NEW.rowid, NEW.id, NEW.quote
            WHERE (SELECT status FROM knowledge_dialogue_annotation_set WHERE id = NEW.annotation_set_id)
                  = 'published';
        END;
CREATE TRIGGER knowledge_dialogue_utterance_fts_delete
        AFTER DELETE ON knowledge_dialogue_utterance
        BEGIN
            DELETE FROM knowledge_dialogue_utterance_fts WHERE rowid = OLD.rowid;
        END;
CREATE TRIGGER knowledge_dialogue_source_snapshot_update
        AFTER UPDATE ON source_current_snapshot
        WHEN OLD.source_id IS NOT NEW.source_id OR OLD.snapshot_id IS NOT NEW.snapshot_id
        BEGIN
            UPDATE knowledge_dialogue_annotation_set
            SET status = 'superseded', updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now')
            WHERE source_id = OLD.source_id AND snapshot_id = OLD.snapshot_id
              AND status = 'published';
        END;
CREATE TRIGGER knowledge_dialogue_source_snapshot_delete
        AFTER DELETE ON source_current_snapshot
        BEGIN
            UPDATE knowledge_dialogue_annotation_set
            SET status = 'superseded', updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now')
            WHERE source_id = OLD.source_id AND status = 'published';
        END;
CREATE TRIGGER knowledge_dialogue_annotation_set_cache_revision
        AFTER UPDATE OF status ON knowledge_dialogue_annotation_set
        WHEN OLD.status IS NOT NEW.status
          AND (OLD.status = 'published' OR NEW.status = 'published')
        BEGIN
            UPDATE embedding_read_cache_revision
            SET knowledge_item_revision = knowledge_item_revision + 1 WHERE singleton = 1;
        END;
CREATE TRIGGER knowledge_dialogue_annotation_set_cache_revision_delete
        AFTER DELETE ON knowledge_dialogue_annotation_set
        WHEN OLD.status = 'published'
        BEGIN
            UPDATE embedding_read_cache_revision
            SET knowledge_item_revision = knowledge_item_revision + 1 WHERE singleton = 1;
        END;
CREATE TRIGGER knowledge_dialogue_annotation_set_fts_update
        AFTER UPDATE OF status ON knowledge_dialogue_annotation_set
        WHEN OLD.status IS NOT NEW.status
        BEGIN
            DELETE FROM knowledge_dialogue_utterance_fts
            WHERE rowid IN (
                SELECT rowid FROM knowledge_dialogue_utterance WHERE annotation_set_id = OLD.id
            );
            INSERT INTO knowledge_dialogue_utterance_fts(rowid, utterance_id, quote)
            SELECT utterance.rowid, utterance.id, utterance.quote
            FROM knowledge_dialogue_utterance AS utterance
            WHERE utterance.annotation_set_id = NEW.id AND NEW.status = 'published';
        END;
CREATE TRIGGER knowledge_dialogue_annotation_set_published_immutable
        BEFORE UPDATE ON knowledge_dialogue_annotation_set
        WHEN OLD.status = 'published'
          AND (
              NEW.status NOT IN ('published', 'superseded')
              OR NEW.id IS NOT OLD.id
              OR NEW.receipt_id IS NOT OLD.receipt_id
              OR NEW.generation IS NOT OLD.generation
              OR NEW.annotation_revision IS NOT OLD.annotation_revision
              OR NEW.parse_batch_id IS NOT OLD.parse_batch_id
              OR NEW.space IS NOT OLD.space
              OR NEW.scope_work_id IS NOT OLD.scope_work_id
              OR NEW.physical_work_id IS NOT OLD.physical_work_id
              OR NEW.branch_id IS NOT OLD.branch_id
              OR NEW.source_id IS NOT OLD.source_id
              OR NEW.snapshot_id IS NOT OLD.snapshot_id
              OR NEW.content_hash IS NOT OLD.content_hash
              OR NEW.utterance_count IS NOT OLD.utterance_count
              OR NEW.annotation_hash IS NOT OLD.annotation_hash
              OR NEW.input_annotation_hash IS NOT OLD.input_annotation_hash
              OR NEW.dialogue_review_proof_json IS NOT OLD.dialogue_review_proof_json
              OR NEW.dialogue_review_status IS NOT OLD.dialogue_review_status
              OR NEW.created_at IS NOT OLD.created_at
          )
        BEGIN
            SELECT RAISE(ABORT, 'published dialogue annotation set is immutable');
        END;
CREATE TRIGGER knowledge_item_published_graph_version_owner
        BEFORE UPDATE OF published_graph_version_id ON knowledge_item
        WHEN NEW.published_graph_version_id IS NOT NULL AND (
            NEW.kind != 'knowledge_graph_candidate'
            OR NOT EXISTS (
                SELECT 1 FROM knowledge_version AS version
                WHERE version.id = NEW.published_graph_version_id
                  AND version.item_id = NEW.id
            )
        )
        BEGIN
            SELECT RAISE(ABORT, 'published graph version must belong to its candidate item');
        END;
CREATE TRIGGER knowledge_item_published_graph_version_insert_owner
        BEFORE INSERT ON knowledge_item
        WHEN NEW.published_graph_version_id IS NOT NULL AND (
            NEW.kind != 'knowledge_graph_candidate'
            OR NOT EXISTS (
                SELECT 1 FROM knowledge_version AS version
                WHERE version.id = NEW.published_graph_version_id
                  AND version.item_id = NEW.id
            )
        )
        BEGIN
            SELECT RAISE(ABORT, 'published graph version must belong to its candidate item');
        END;
CREATE TRIGGER knowledge_item_published_graph_version_invalidate
        AFTER UPDATE OF status ON knowledge_item
        WHEN NEW.status IN ('deleted', 'rejected', 'superseded')
          AND NEW.published_graph_version_id IS NOT NULL
        BEGIN
            UPDATE knowledge_item SET published_graph_version_id = NULL WHERE id = NEW.id;
        END;
CREATE TRIGGER knowledge_parse_submission_request_immutable
        BEFORE UPDATE OF id, client_batch_id, scope_key, space, work_id,
                         request_hash, request_json, initial_failures_json,
                         total_sources, created_at
        ON knowledge_parse_submission
        BEGIN
            SELECT RAISE(ABORT, 'parse submission request identity and plan are immutable');
        END;
CREATE TRIGGER knowledge_parse_submission_child_plan_immutable
        BEFORE UPDATE OF id, submission_id, ordinal, client_batch_id,
                         request_json, created_at
        ON knowledge_parse_submission_child
        BEGIN
            SELECT RAISE(ABORT, 'parse submission child plan is immutable');
        END;
CREATE TRIGGER knowledge_parse_submission_child_transition
        BEFORE UPDATE OF status ON knowledge_parse_submission_child
        WHEN NOT (OLD.status = NEW.status OR OLD.status = 'pending')
        BEGIN
            SELECT RAISE(ABORT, 'parse submission child transition is invalid or terminal');
        END;
CREATE TRIGGER knowledge_parse_submission_child_terminal_immutable
        BEFORE UPDATE ON knowledge_parse_submission_child
        WHEN OLD.status IN ('accepted', 'failed')
          AND (
              NEW.status IS NOT OLD.status
              OR NEW.batch_id IS NOT OLD.batch_id
              OR NEW.failure_json IS NOT OLD.failure_json
          )
        BEGIN
            SELECT RAISE(ABORT, 'parse submission child result is immutable');
        END;
CREATE TRIGGER knowledge_parse_processing_unit_scope_immutable
        BEFORE UPDATE OF id, batch_id, phase, folder_id, group_ref, input_hash, prompt_hash,
                         input_fingerprint, source_pins_json, candidate_refs_json,
                         manifest_pin_json, created_at
        ON knowledge_parse_processing_unit
        BEGIN
            SELECT RAISE(ABORT, 'parse processing unit scope is immutable');
        END;
CREATE TRIGGER knowledge_parse_processing_unit_state_transition
        BEFORE UPDATE OF execution_status ON knowledge_parse_processing_unit
        WHEN NOT (
            OLD.execution_status = NEW.execution_status
            OR (OLD.execution_status IN ('prepared', 'failed')
                AND NEW.execution_status IN ('running', 'stale'))
            OR (OLD.execution_status = 'running'
                AND NEW.execution_status IN ('failed', 'completed', 'stale', 'superseded'))
        )
        BEGIN
            SELECT RAISE(ABORT, 'parse processing unit state transition is invalid');
        END;
CREATE TRIGGER knowledge_parse_processing_unit_batch_fenced
        AFTER UPDATE OF status ON knowledge_parse_batch
        WHEN OLD.status = 'running' AND NEW.status != 'running'
        BEGIN
            UPDATE knowledge_parse_processing_unit
            SET execution_status = 'stale',
                outcome_json = json_object('reason', 'batch_terminal'),
                updated_at = NEW.updated_at
            WHERE batch_id = NEW.id AND execution_status IN ('prepared', 'running');
        END;
CREATE TRIGGER knowledge_reviewed_claim_publication_immutable
        BEFORE UPDATE ON knowledge_reviewed_claim_publication
        BEGIN
            SELECT RAISE(ABORT, 'reviewed claim publication receipts are immutable');
        END;
CREATE TRIGGER knowledge_item_retirement_authorization_scope_insert
        BEFORE INSERT ON knowledge_item_retirement_authorization
        WHEN NOT EXISTS (
            SELECT 1 FROM knowledge_item AS item
            WHERE item.id = NEW.item_id AND item.kind = 'knowledge_graph_candidate'
              AND item.status = 'deleted'
              AND item.space = NEW.space AND item.work_id IS NEW.work_id
        )
        BEGIN SELECT RAISE(ABORT, 'retirement authorization requires a deleted candidate in the same scope'); END;
CREATE TRIGGER knowledge_reviewed_claim_source_retirement_authorization_scope_insert
        BEFORE INSERT ON knowledge_reviewed_claim_source_retirement_authorization
        WHEN NOT EXISTS (
            SELECT 1
            FROM knowledge_reviewed_claim_publication AS publication
            JOIN knowledge_item AS item ON item.id = publication.candidate_item_id
            JOIN source ON source.id = publication.source_id
            JOIN source_snapshot AS snapshot
              ON snapshot.id = publication.snapshot_id
             AND snapshot.source_id = publication.source_id
            WHERE publication.id = NEW.publication_id
              AND publication.candidate_item_id = NEW.candidate_item_id
              AND publication.source_id = NEW.source_id
              AND publication.snapshot_id = NEW.snapshot_id
              AND publication.space = NEW.space
              AND publication.work_id IS NEW.work_id
              AND source.id = NEW.source_id
              AND source.space = NEW.space
              AND source.work_id IS NEW.work_id
              AND snapshot.id = NEW.snapshot_id
              AND item.kind = 'knowledge_graph_candidate'
              AND item.status NOT IN ('deleted', 'rejected', 'superseded')
              AND item.space = NEW.space AND item.work_id IS NEW.work_id
        )
        BEGIN SELECT RAISE(ABORT, 'source proof retirement must match a retained candidate and exact source snapshot'); END;
CREATE TRIGGER knowledge_reviewed_claim_source_retirement_authorization_no_update
        BEFORE UPDATE ON knowledge_reviewed_claim_source_retirement_authorization
        BEGIN SELECT RAISE(ABORT, 'source proof retirement authorization is immutable'); END;
CREATE TRIGGER knowledge_reviewed_claim_source_retirement_authorization_no_delete_while_proof_exists
        BEFORE DELETE ON knowledge_reviewed_claim_source_retirement_authorization
        WHEN EXISTS (
            SELECT 1 FROM knowledge_reviewed_claim_publication AS publication
            WHERE publication.id = OLD.publication_id
        )
        BEGIN SELECT RAISE(ABORT, 'source proof retirement authorization cannot be removed before its exact proof'); END;
CREATE TRIGGER knowledge_claim_base_scope_insert
        BEFORE INSERT ON knowledge_claim_base_revision
        WHEN NOT EXISTS (
            SELECT 1 FROM knowledge_item AS item
            WHERE item.id = NEW.item_id AND item.kind = 'knowledge_graph_candidate'
              AND item.space = NEW.space AND item.work_id IS NEW.work_id
        )
        BEGIN SELECT RAISE(ABORT, 'base claim scope must match graph candidate'); END;
CREATE TRIGGER knowledge_claim_interpretation_scope_insert
        BEFORE INSERT ON knowledge_claim_interpretation
        WHEN NOT EXISTS (
            SELECT 1 FROM knowledge_item AS item
            WHERE item.id = NEW.item_id AND item.kind = 'knowledge_graph_candidate'
              AND item.space = NEW.space AND item.work_id IS NEW.work_id
        )
        BEGIN SELECT RAISE(ABORT, 'claim interpretation scope must match graph candidate'); END;
CREATE TRIGGER knowledge_claim_version_scope_insert
        BEFORE INSERT ON knowledge_claim_version_component
        WHEN NOT EXISTS (
            SELECT 1 FROM knowledge_item AS item
            JOIN knowledge_version AS version ON version.item_id = item.id
            WHERE item.id = NEW.item_id AND item.kind = 'knowledge_graph_candidate'
              AND item.space = NEW.space AND item.work_id IS NEW.work_id
              AND version.id = NEW.knowledge_version_id
        )
        BEGIN SELECT RAISE(ABORT, 'claim version scope must match graph candidate version'); END;
CREATE TRIGGER knowledge_claim_base_no_update
        BEFORE UPDATE ON knowledge_claim_base_revision
        BEGIN SELECT RAISE(ABORT, 'claim base revisions are append-only'); END;
CREATE TRIGGER knowledge_claim_interpretation_no_update
        BEFORE UPDATE ON knowledge_claim_interpretation
        BEGIN SELECT RAISE(ABORT, 'claim interpretations are append-only'); END;
CREATE TRIGGER knowledge_claim_version_component_no_update
        BEFORE UPDATE ON knowledge_claim_version_component
        BEGIN SELECT RAISE(ABORT, 'claim version composition is immutable'); END;
CREATE TRIGGER knowledge_claim_base_no_delete
        BEFORE DELETE ON knowledge_claim_base_revision
        WHEN NOT EXISTS (
            SELECT 1 FROM knowledge_item_retirement_authorization AS authorization
            JOIN knowledge_item AS item ON item.id = authorization.item_id
            WHERE authorization.item_id = OLD.item_id AND item.status = 'deleted'
        )
        BEGIN SELECT RAISE(ABORT, 'claim base deletion requires the selected-item purge owner'); END;
CREATE TRIGGER knowledge_claim_interpretation_no_delete
        BEFORE DELETE ON knowledge_claim_interpretation
        WHEN NOT EXISTS (
            SELECT 1 FROM knowledge_item_retirement_authorization AS authorization
            JOIN knowledge_item AS item ON item.id = authorization.item_id
            WHERE authorization.item_id = OLD.item_id AND item.status = 'deleted'
        )
        BEGIN SELECT RAISE(ABORT, 'claim interpretation deletion requires the selected-item purge owner'); END;
CREATE TRIGGER knowledge_claim_version_component_no_delete
        BEFORE DELETE ON knowledge_claim_version_component
        WHEN NOT EXISTS (
            SELECT 1 FROM knowledge_item_retirement_authorization AS authorization
            JOIN knowledge_item AS item ON item.id = authorization.item_id
            WHERE authorization.item_id = OLD.item_id AND item.status = 'deleted'
        )
        BEGIN SELECT RAISE(ABORT, 'claim composition deletion requires the selected-item purge owner'); END;
CREATE TRIGGER knowledge_reviewed_claim_publication_no_delete
        BEFORE DELETE ON knowledge_reviewed_claim_publication
        WHEN NOT EXISTS (
            SELECT 1 FROM knowledge_item_retirement_authorization AS authorization
            JOIN knowledge_item AS item ON item.id = authorization.item_id
            WHERE authorization.item_id = OLD.candidate_item_id AND item.status = 'deleted'
        ) AND NOT EXISTS (
            SELECT 1 FROM knowledge_reviewed_claim_source_retirement_authorization AS authorization
            WHERE authorization.publication_id = OLD.id
              AND authorization.owner_kind = 'source_purge'
              AND authorization.candidate_item_id = OLD.candidate_item_id
              AND authorization.source_id = OLD.source_id
              AND authorization.snapshot_id = OLD.snapshot_id
              AND authorization.space = OLD.space
              AND authorization.work_id IS OLD.work_id
        )
        BEGIN SELECT RAISE(ABORT, 'reviewed claim publication deletion requires an exact item or source purge owner'); END;
CREATE TRIGGER knowledge_query_review_receipt_identity_insert
        BEFORE INSERT ON knowledge_query_review_receipt
        WHEN json_extract(NEW.proof_json, '$.receipt_id') IS NOT NEW.id
          OR json_extract(NEW.proof_json, '$.query_spec.scope.space') IS NOT NEW.space
          OR json_extract(NEW.proof_json, '$.query_spec.scope.work_id') IS NOT NEW.work_id
          OR json_extract(NEW.proof_json, '$.query_spec.scope.branch') IS NOT NEW.branch_id
          OR json_extract(NEW.proof_json, '$.review_receipt.provider_model') IS NOT NEW.provider_model
          OR json_extract(NEW.proof_json, '$.review_receipt.model_input_sha256') IS NOT NEW.model_input_sha256
          OR json_extract(NEW.proof_json, '$.review_receipt.prompt_sha256') IS NOT NEW.prompt_sha256
          OR json_extract(NEW.proof_json, '$.review_receipt.response_sha256') IS NOT NEW.response_sha256
          OR json(json_extract(NEW.proof_json, '$.review_receipt.requirement_ids'))
                IS NOT json(NEW.requirement_ids_json)
          OR json(json_extract(NEW.proof_json, '$.review_receipt.evidence_scopes'))
                IS NOT json(NEW.scope_pins_json)
        BEGIN
            SELECT RAISE(ABORT, 'query review receipt must preserve its exact request and model proof');
        END;
CREATE TRIGGER knowledge_query_review_receipt_immutable
        BEFORE UPDATE ON knowledge_query_review_receipt
        WHEN OLD.id IS NOT NEW.id
          OR OLD.space IS NOT NEW.space
          OR OLD.work_id IS NOT NEW.work_id
          OR OLD.branch_id IS NOT NEW.branch_id
          OR OLD.provider_model IS NOT NEW.provider_model
          OR OLD.model_input_sha256 IS NOT NEW.model_input_sha256
          OR OLD.prompt_sha256 IS NOT NEW.prompt_sha256
          OR OLD.response_sha256 IS NOT NEW.response_sha256
          OR OLD.requirement_ids_json IS NOT NEW.requirement_ids_json
          OR OLD.scope_pins_json IS NOT NEW.scope_pins_json
          OR OLD.proof_json IS NOT NEW.proof_json
          OR OLD.created_at IS NOT NEW.created_at
          OR NOT (
              (OLD.status = 'pending' AND NEW.status IN ('published', 'failed'))
              OR (OLD.status = 'failed' AND OLD.failure_code = 'projection_failed'
                  AND NEW.status = 'pending' AND NEW.failure_code IS NULL)
          )
        BEGIN
            SELECT RAISE(ABORT, 'query review proof is immutable; only owner status recovery is permitted');
        END;
CREATE TRIGGER knowledge_query_review_receipt_no_delete
        BEFORE DELETE ON knowledge_query_review_receipt
        BEGIN
            SELECT RAISE(ABORT, 'query review receipts are durable recovery records');
        END;
CREATE TRIGGER knowledge_query_claim_publication_immutable
        BEFORE UPDATE ON knowledge_query_reviewed_claim_publication
        BEGIN
            SELECT RAISE(ABORT, 'query claim publication records are immutable');
        END;
CREATE TRIGGER knowledge_query_claim_publication_no_delete
        BEFORE DELETE ON knowledge_query_reviewed_claim_publication
        BEGIN
            SELECT RAISE(ABORT, 'query claim publication records are immutable');
        END;
CREATE TRIGGER knowledge_query_claim_publication_scope_insert
        BEFORE INSERT ON knowledge_query_reviewed_claim_publication
        WHEN NOT EXISTS (
            SELECT 1
            FROM knowledge_query_review_receipt AS receipt
            JOIN knowledge_item AS candidate ON candidate.id = NEW.candidate_item_id
            JOIN knowledge_version AS version
              ON version.id = NEW.candidate_version_id
             AND version.item_id = candidate.id
            WHERE receipt.id = NEW.receipt_id
              AND receipt.status = 'pending'
              AND receipt.space = json_extract(receipt.proof_json, '$.query_spec.scope.space')
              AND receipt.work_id IS json_extract(receipt.proof_json, '$.query_spec.scope.work_id')
              AND receipt.branch_id IS json_extract(receipt.proof_json, '$.query_spec.scope.branch')
              AND candidate.id = NEW.candidate_item_id
              AND candidate.kind = 'knowledge_graph_candidate'
              AND candidate.space = NEW.space
              AND candidate.work_id IS NEW.work_id
              AND candidate.published_graph_version_id = version.id
              AND candidate.origin_parse_receipt_id IS NULL
              AND candidate.status NOT IN ('deleted', 'rejected', 'superseded')
              AND json_type(version.content_json, '$.query_learning_claim') = 'object'
              AND json_extract(version.content_json, '$.candidate_role') = 'fact'
              AND json(json_remove(
                    json_extract(version.content_json, '$.query_learning_claim'),
                    '$.requirement_id', '$.evidence_refs'
                  ))
                    = json(json_remove(NEW.claim_json, '$.requirement_id', '$.evidence_refs'))
              AND json(NEW.claim_json) = json(json_extract(
                  receipt.proof_json, '$.claims[' || NEW.claim_ordinal || ']'
              ))
              AND json_extract(NEW.claim_json, '$.requirement_id') IN (
                  SELECT value FROM json_each(receipt.requirement_ids_json)
              )
              AND json_array_length(NEW.evidence_refs_json) > 0
              AND json(json_extract(NEW.claim_json, '$.evidence_refs'))
                    = json(NEW.evidence_refs_json)
              AND NOT EXISTS (
                  SELECT 1 FROM json_each(NEW.evidence_refs_json) AS pinned_ref
                  WHERE NOT EXISTS (
                      SELECT 1
                      FROM knowledge_version_evidence AS link
                      JOIN evidence_span AS span ON span.id = link.evidence_span_id
                      JOIN source_snapshot AS snapshot ON snapshot.id = span.snapshot_id
                      JOIN source ON source.id = snapshot.source_id
                      WHERE link.knowledge_version_id = version.id
                        AND source.id = json_extract(pinned_ref.value, '$.source_id')
                        AND snapshot.id = json_extract(pinned_ref.value, '$.snapshot_id')
                        AND snapshot.content_hash = json_extract(pinned_ref.value, '$.content_hash')
                        AND span.start_offset = json_extract(pinned_ref.value, '$.start_offset')
                        AND span.end_offset = json_extract(pinned_ref.value, '$.end_offset')
                        AND span.quote_hash = json_extract(pinned_ref.value, '$.quote_hash')
                        AND substr(snapshot.content, span.start_offset + 1,
                                   span.end_offset - span.start_offset)
                            = json_extract(pinned_ref.value, '$.quote')
                  )
              )
        )
        BEGIN
            SELECT RAISE(ABORT, 'query claim publication must match its immutable checked claim and exact candidate version');
        END;
